const DEFAULT_PROFILE = { name: "", age: "", sex: "", height: "", weight: "", goal: "", activity: "", meals: 3, disliked: [] as string[], allergies: [] as string[], allergyNote: "", budget: "", cookTime: 0, prep: null as any, mode: "" as string, exp: "", meds: null as any, diseases: null as any };
function loadStore() {
  try { const s = JSON.parse(localStorage.getItem("kb_state_v1") || "null"); if (s) return s; } catch (e) { }
  return { profile: { ...DEFAULT_PROFILE }, onboarded: false, premium: false, theme: "light", accent: "sage", day: dayISO(), diary: {} as any, water: {} as any, doneDishes: {} as any, cooked: {} as any, fav: {} as any, pantry: [] as string[], hasItems: [] as string[], shopping: { items: [] as any[], checked: {} as any }, menu: null as any, lessons: {} as any, quiz: null as any, ach: {} as any, remSet: { level: "standard", custom: {} as any }, chat: [] as any[], msgs: [] as any[], consult: null as any, homeTxt: { sub: "Меню, рецепты и наблюдение за самочувствием — без жёстких правил" }, admin: null as any, weekReview: null as any };
}
let store: any = loadStore();
let listeners: (() => void)[] = [];
const emit = () => { localStorage.setItem("kb_state_v1", JSON.stringify(store)); listeners.forEach(f => f()); };
function useStore() { const [, s] = useState(0); useEffect(() => { const f = () => s(x => x + 1); listeners.push(f); return () => { listeners = listeners.filter(x => x !== f); }; }, []); return store; }
const setSt = (fn: (s: any) => void) => { fn(store); emit(); };
const P = () => store.profile;
const MODE = (): Mode => (P().mode || "explore") as Mode;

function pool(mode: string) { return RECIPES.filter(r => r.mode === mode); }
function genMenu(mode: string, numDays: number, meals: number) {
  const b = pool(mode); const used = new Set<string>();
  const pick = (cat?: string) => { const c = b.filter(r => (!cat || r.cat === cat) && !used.has(r.id)); const src = c.length ? c : b.filter(r => !used.has(r.id)); return src[Math.floor(Math.random() * src.length)] || b[0]; };
  const idsByDay: string[][] = [];
  for (let d = 0; d < numDays; d++) {
    const ids: string[] = [];
    if (meals >= 2) { const r = pick("breakfast"); ids.push(r.id); used.add(r.id); }
    if (meals >= 3) { const r = pick("lunch"); ids.push(r.id); used.add(r.id); }
    const rd = pick("dinner"); ids.push(rd.id); used.add(rd.id);
    if (meals >= 4) { const r = pick(Math.random() > 0.5 ? "snack" : "dessert"); ids.push(r.id); used.add(r.id); }
    idsByDay.push(ids);
  }
  const dis: string[] = P().disliked || [];
  idsByDay.forEach(day => day.forEach((id, i) => { const r = RECIPES.find(x => x.id === id)!; if (r.ing.some(([n]) => dis.some(d0 => n.includes(d0)))) { const alt = b.filter(x => !day.includes(x.id) && x.cat === r.cat && !x.ing.some(([n]) => dis.some(d0 => n.includes(d0)))); if (alt.length) day[i] = alt[Math.floor(Math.random() * alt.length)].id; } }));
  return { mode, meals, portion: 1, saved: false, created: Date.now(), days: idsByDay.map((ids, i) => ({ date: dayISO(addDays(i)), slots: Object.fromEntries(ids.map(id => [RECIPES.find(x => x.id === id)!.cat, id])) })) };
}
const ingAmount = (a: string) => { const m = a.match(/([\d.,]+)/); return m ? parseFloat(m[1].replace(",", ".")) || 1 : 1; };
function menuIng(menu: any) { const map: any = {}; const mult = menu.portion || 1; menu.days.forEach((d: any) => Object.values(d.slots).forEach((id: any) => { const r = RECIPES.find(x => x.id === id); if (!r) return; r.ing.forEach(([name, amt]) => { const e = map[name] || (map[name] = { name, qty: 0, unit: amt.replace(/[\d.,\s]+/, "").trim() || "шт", cost: 0 }); e.qty += ingAmount(amt) * mult; e.cost += ingAmount(amt) * mult * ((FOODS.find(f => f[0] === name)?.[2] || 0) / 10); }); })); return Object.values(map); }
function shoppingItems(menu: any) { return menuIng(menu).filter((i: any) => !store.hasItems.includes(i.name)).map((i: any) => ({ id: uid(), name: i.name, qty: i.qty, unit: i.unit, cost: i.cost, custom: false })); }
function reminderState() { const { level, custom } = store.remSet; return REMS.map(r => ({ on: level === "custom" ? !!custom[r.id] : level === "minimal" ? r.id === "diary" : level === "active" ? true : r.def, ...r })); }
function checkAch() { const a = store.ach; const set = (id: string) => { if (!a[id]) a[id] = Date.now(); }; const dcnt = Object.keys(store.diary).length; if (dcnt >= 1) set("first"); if (dcnt >= 3) set("d3"); if (Object.keys(store.fav).length >= 1) set("fav1"); if (store.menu) set("menu"); if (store.menu && store.menu.days.length >= 7) set("week"); if (Object.keys(store.cooked).length >= 1) set("cook"); if (store.shopping.items.length) set("list"); if (Object.keys(store.lessons).length >= 5) set("course"); }
function diaryInsights() { const out: { t: string; tone: string }[] = []; const days = Object.keys(store.diary).sort().slice(-7).map(d => store.diary[d]); const last = days.slice(-3); if (last.length >= 3 && last.every(d => d.energy <= 2)) out.push({ t: "Энергия снизилась несколько дней подряд. Проверьте, достаточно ли вы едите и отдыхаете.", tone: "warn" }); if (days.filter(d => d.symp?.includes("Головокружение")).length >= 2) out.push({ t: "Вы несколько раз отмечали головокружение. Не игнорируйте этот симптом — обсудите со специалистом.", tone: "warn" }); if (last.length >= 3 && last.every(d => d.sleep <= 2) && last.some(d => d.craving >= 4)) out.push({ t: "Похоже, сон влияет на аппетит. Попробуйте обратить внимание на режим отдыха.", tone: "ok" }); if (days.some(d => d.symp?.includes("Судороги"))) out.push({ t: "Вы отмечали судороги. Если они повторяются, обсудите питание и питьевой режим с врачом.", tone: "warn" }); if (last.length >= 2 && last.every(d => d.mood >= 4 && d.energy >= 4)) out.push({ t: "Хорошая неделя: стабильная энергия и настроение. Продолжайте в своём темпе.", tone: "good" }); return out; }
function botReply(text: string) { const t = text.toLowerCase(); const m = MODE(); if (/привет|здрав|добр/.test(t)) return "Здравствуйте! Помогу с меню, рецептами и списками покупок. Что интересует?"; if (/кето/.test(t)) return m === "keto" ? "Вы в режиме кето 🥑 Загляните в «Кето»: правила, продукты, меню. При заболеваниях — сначала к врачу." : "Кето — рацион с очень низким количеством углеводов. Начните с урока 1 и программы «Мягкий старт». Кето не лечит, при заболеваниях нужна консультация врача."; if (/карнивор/.test(t)) return m === "carnivore" ? "Вы в режиме карнивор 🥩 Простые рецепты и заготовки уже подобраны. Наблюдайте за пищеварением." : "Карнивор — ограничительный формат на основе животных продуктов. Подходит не каждому: сравните варианты в «Какой формат подойдёт»."; if (/меню|план/.test(t)) return "Меню собирается в разделе «Меню»: период 1/3/7 дней, с учётом аллергий и нелюбимых продуктов. Любое блюдо можно заменить."; if (/покуп|список/.test(t)) return "Список покупок собирается автоматически из меню — объединяет продукты и делит по категориям. Раздел «Покупки»."; if (/сорв|тяг|сладк/.test(t)) return "Откройте «Антисрыв» на главном экране — мягкий план без чувства вины."; if (/врач|боле|лекарств/.test(t)) return "При заболеваниях, лекарствах, беременности и кормлении рацион обсуждается с врачом заранее. При острых симптомах — сразу за медицинской помощью."; if (/спасибо/.test(t)) return "Пожалуйста! Я на связи каждый день 🌿"; return "Подскажу по меню, рецептам, покупкам или самочувствию. По сложным вопросам — раздел «Мой нутрициолог»."; }

/* ================= 4. UI-ПРИМИТИВЫ ================= */
function useRoute() { const [r, s] = useState(location.hash.slice(1) || "/home"); useEffect(() => { const f = () => { s(location.hash.slice(1) || "/home"); window.scrollTo(0, 0); }; addEventListener("hashchange", f); return () => removeEventListener("hashchange", f); }, []); const parts = r.split("/").filter(Boolean); return { path: "/" + (parts[0] || "home"), parts }; }
const go = (r: string) => { location.hash = r; };
function Btn({ children, onClick, variant = "primary", cls = "", disabled }: any) { const v: any = { primary: "text-white shadow-sm", soft: "bg-black/5 dark:bg-white/10", ghost: "text-stone-600 dark:text-stone-300", danger: "bg-red-600 text-white" }; const st = variant === "primary" ? { background: "var(--acc)" } : {}; return <button disabled={disabled} onClick={onClick} className={`px-4 py-2.5 rounded-xl font-semibold text-sm transition active:scale-[.98] disabled:opacity-50 ${v[variant]} ${cls}`} style={st}>{children}</button>; }
function Card({ children, cls = "", onClick }: any) { return <div onClick={onClick} className={`bg-white dark:bg-[#26221C] rounded-2xl border border-stone-200/80 dark:border-white/10 shadow-sm ${cls}`}>{children}</div>; }
function Chip({ on, onClick, children }: any) { return <button onClick={onClick} className={`px-3 py-1.5 rounded-full text-sm font-medium border transition whitespace-nowrap ${on ? "text-white border-transparent" : "bg-white dark:bg-white/5 border-stone-200 dark:border-white/15 text-stone-600 dark:text-stone-300"}`} style={on ? { background: "var(--acc)" } : {}}>{children}</button>; }
function Modal({ open, onClose, children, title }: any) { if (!open) return null; return <div className="fixed inset-0 z-50 flex items-end sm:items-center justify-center bg-black/40 p-0 sm:p-6" onClick={onClose}><div className="w-full sm:max-w-lg bg-[#FDFBF6] dark:bg-[#26221C] rounded-t-3xl sm:rounded-3xl p-5 max-h-[88vh] overflow-y-auto" onClick={(e: any) => e.stopPropagation()}><div className="flex justify-between items-center mb-3"><div className="text-lg font-bold">{title}</div><button onClick={onClose} className="w-8 h-8 rounded-full bg-black/5 dark:bg-white/10">✕</button></div>{children}</div></div>; }
function Field({ label, children, hint }: any) { return <div className="mb-4"><label className="block text-sm font-semibold mb-1.5">{label}</label>{children}{hint && <div className="text-xs text-stone-400 mt-1">{hint}</div>}</div>; }
const Input = ({ cls = "", ...rest }: any) => <input {...rest} className={`w-full px-3.5 py-2.5 rounded-xl border border-stone-200 dark:border-white/15 bg-white dark:bg-white/5 text-[15px] outline-none ${cls}`} />;
function Seg({ opts, val, set }: any) { return <div className="grid grid-cols-2 gap-2">{opts.map((o: any) => <button key={String(o.v)} onClick={() => set(o.v)} className={`px-3 py-2.5 rounded-xl text-sm font-semibold border transition ${val === o.v ? "text-white border-transparent" : "border-stone-200 dark:border-white/15 text-stone-600 dark:text-stone-300 bg-white dark:bg-white/5"}`} style={val === o.v ? { background: "var(--acc)" } : {}}>{o.l}</button>)}</div>; }
function Scale({ val, set, low, high }: any) { return <div><div className="flex gap-1.5">{[1, 2, 3, 4, 5].map(n => <button key={n} onClick={() => set(n)} className="flex-1 py-2 rounded-lg text-sm font-bold border" style={val === n ? { background: "var(--acc)", color: "#fff", borderColor: "transparent" } : { borderColor: "rgba(120,113,108,.25)", color: "var(--acc)" }}>{n}</button>)}</div><div className="flex justify-between text-[10px] text-stone-400 mt-0.5"><span>{low}</span><span>{high}</span></div></div>; }
function Toast({ msg, onClose }: any) { useEffect(() => { const t = setTimeout(onClose, 3500); return () => clearTimeout(t); }, []); return <div className="fixed bottom-24 sm:bottom-8 left-1/2 -translate-x-1/2 z-[60] bg-stone-900 text-white px-5 py-3 rounded-2xl shadow-xl text-sm max-w-sm text-center">{msg}</div>; }
function FoodPic({ r, big }: any) { return <div className={`${big ? "h-56 sm:h-72 rounded-3xl" : "h-36 rounded-2xl"} w-full flex items-center justify-center relative overflow-hidden`} style={{ background: `linear-gradient(135deg,${r.g[0]},${r.g[1]})` }}><span className={big ? "text-8xl" : "text-6xl"} style={{ filter: "drop-shadow(0 6px 12px rgba(0,0,0,.18))" }}>{r.emoji}</span><div className="absolute bottom-2 left-2 flex gap-1 flex-wrap max-w-[85%]">{r.tags.slice(0, 2).map((t: string) => <span key={t} className="text-[10px] px-2 py-0.5 rounded-full bg-white/80 text-stone-700 font-semibold">{t}</span>)}</div></div>; }
const Lvl = ({ n }: any) => <span className={`text-[10px] px-1.5 py-0.5 rounded ${n === "легко" ? "bg-emerald-100 text-emerald-700 dark:bg-emerald-900/40 dark:text-emerald-300" : n === "средне" ? "bg-amber-100 text-amber-700 dark:bg-amber-900/40 dark:text-amber-300" : "bg-red-100 text-red-700"}`}>{n}</span>;
const Stars = ({ c }: any) => <span className="text-[11px] font-bold" style={{ color: "var(--acc)" }}>{COST[c]}</span>;
function Line({ vals, h = 90 }: any) { const pts = vals.map((v: number, i: number) => [i * (100 / Math.max(vals.length - 1, 1)), h - v / 5 * h]); const d = "M" + pts.map((p: number[]) => p.join(",")).join(" L"); return <svg viewBox={`0 0 100 ${h}`} className="w-full" preserveAspectRatio="none" style={{ height: h }}>{vals.length > 1 && <path d={d} fill="none" stroke="var(--acc)" strokeWidth="2.5" strokeLinecap="round" />}{vals.map((v: number, i: number) => <circle key={i} cx={i * (100 / Math.max(vals.length - 1, 1))} cy={h - v / 5 * h} r="3" fill="var(--acc)" />)}</svg>; }
function Empty({ e, t, d, btn, onClick, children }: any) { return <div className="text-center py-12 px-6"><div className="text-5xl mb-3">{e}</div><div className="font-semibold mb-1">{t}</div><div className="text-sm text-stone-500 mb-4 max-w-xs mx-auto">{d}</div>{btn && <Btn onClick={onClick}>{btn}</Btn>}{children}</div>; }
function Toggle({ on, set, label }: any) { return <button onClick={() => set(!on)} className="flex items-center gap-3 py-1"><span className={`w-11 h-6 rounded-full p-0.5 transition ${on ? "" : "bg-stone-300 dark:bg-white/15"}`} style={on ? { background: "var(--acc)" } : {}}><span className={`block w-5 h-5 bg-white rounded-full transition ${on ? "translate-x-5" : ""}`} /></span><span className="text-sm font-medium">{label}</span></button>; }
const Stat = ({ v, l, e }: any) => <div className="text-center"><div className="text-2xl">{e}</div><div className="text-xl font-bold">{v}</div><div className="text-[11px] text-stone-500">{l}</div></div>;

/* ================= 5. ОНБОРДИНГ ================= */
function Onboarding() { const st = useStore(); const [step, setStep] = useState(0); const p: any = { ...st.profile }; const up = (patch: any) => setSt(s => { Object.assign(s.profile, patch); });
  const steps: any[] = [
    <div key="s0" className="text-center"><div className="text-6xl mb-4">🥑</div><h1 className="text-3xl font-bold mb-3">Кето Баланс</h1><p className="text-stone-500 mb-2">{st.homeTxt.sub}</p><p className="text-sm text-stone-400 max-w-sm mx-auto mb-6">Ответьте на несколько вопросов — и приложение соберёт меню, рецепты и списки покупок под вашу жизнь.</p><Btn onClick={() => setStep(1)} cls="w-full">Начать →</Btn></div>,
    <div key="s1"><h2 className="text-xl font-bold mb-3">Как вас зовут?</h2><Field label="Имя"><Input value={p.name} onChange={(e: any) => up({ name: e.target.value })} placeholder="Например, Анна" /></Field><Field label="Возраст"><Input type="number" value={p.age} onChange={(e: any) => up({ age: e.target.value })} placeholder="35" /></Field><Btn cls="w-full" disabled={!p.name.trim() || !p.age} onClick={() => setStep(2)}>Дальше</Btn></div>,
    <div key="s2"><h2 className="text-xl font-bold mb-3">Ваш пол</h2><Seg opts={[{ v: "ж", l: "Женский" }, { v: "м", l: "Мужской" }]} val={p.sex} set={(v: any) => up({ sex: v })} /><Btn cls="w-full mt-4" disabled={!p.sex} onClick={() => setStep(3)}>Дальше</Btn></div>,
    <div key="s3"><h2 className="text-xl font-bold mb-3">Рост и вес</h2><p className="text-xs text-stone-400 mb-3">Необязательно — только для отслеживания динамики. Мы не продвигаем ежедневные взвешивания.</p><div className="grid grid-cols-2 gap-3"><Field label="Рост, см"><Input type="number" value={p.height} onChange={(e: any) => up({ height: e.target.value })} /></Field><Field label="Вес, кг"><Input type="number" value={p.weight} onChange={(e: any) => up({ weight: e.target.value })} /></Field></div><Btn cls="w-full" onClick={() => setStep(4)}>Дальше</Btn></div>,
    <div key="s4"><h2 className="text-xl font-bold mb-3">Что для вас важнее всего?</h2>{["Снижение веса", "Поддержание формы", "Меньше тяги к сладкому", "Больше энергии", "Упростить питание", "Познакомиться с новым рационом"].map(g => <button key={g} onClick={() => up({ goal: g })} className={`w-full text-left px-4 py-3 rounded-xl border mb-2 text-sm font-medium ${p.goal === g ? "text-white border-transparent" : "border-stone-200 dark:border-white/15"}`} style={p.goal === g ? { background: "var(--acc)" } : {}}>{g}</button>)}<Btn cls="w-full" disabled={!p.goal} onClick={() => setStep(5)}>Дальше</Btn></div>,
    <div key="s5"><h2 className="text-xl font-bold mb-3">Физическая активность</h2><Seg opts={[{ v: "low", l: "Низкая" }, { v: "mid", l: "Умеренная" }, { v: "high", l: "Высокая" }]} val={p.activity} set={(v: any) => up({ activity: v })} /><Btn cls="w-full mt-4" disabled={!p.activity} onClick={() => setStep(6)}>Дальше</Btn></div>,
    <div key="s6"><h2 className="text-xl font-bold mb-3">Сколько приёмов пищи?</h2><Seg opts={[{ v: 2, l: "2 приёма" }, { v: 3, l: "3 приёма" }, { v: 4, l: "4 приёма" }]} val={p.meals} set={(v: any) => up({ meals: v })} /><Btn cls="w-full mt-4" onClick={() => setStep(7)}>Дальше</Btn></div>,
    <div key="s7"><h2 className="text-xl font-bold mb-3">Что вы не любите есть?</h2><p className="text-xs text-stone-400 mb-3">Эти продукты не попадут в меню.</p><div className="flex flex-wrap gap-2">{["Печень и субпродукты", "Грибы", "Рыба", "Авокадо", "Брокколи", "Лук", "Болгарский перец", "Морепродукты"].map(x => { const on = p.disliked.includes(x); return <Chip key={x} on={on} onClick={() => up({ disliked: on ? p.disliked.filter((y: string) => y !== x) : [...p.disliked, x] })}>{x}</Chip>; })}</div><Btn cls="w-full mt-4" onClick={() => setStep(8)}>Дальше</Btn></div>,
    <div key="s8"><h2 className="text-xl font-bold mb-3">Аллергии и непереносимости</h2><div className="flex flex-wrap gap-2 mb-4">{["Яйца", "Молочные продукты", "Рыба", "Орехи"].map(x => { const on = p.allergies.includes(x); return <Chip key={x} on={on} onClick={() => up({ allergies: on ? p.allergies.filter((y: string) => y !== x) : [...p.allergies, x] })}>{x}</Chip>; })}</div><Field label="Другое (своими словами)"><Input value={p.allergyNote || ""} onChange={(e: any) => up({ allergyNote: e.target.value })} placeholder="Например: цитрусовые" /></Field><Btn cls="w-full" onClick={() => setStep(9)}>Дальше</Btn></div>,
    <div key="s9"><h2 className="text-xl font-bold mb-3">Бюджет и готовка</h2><Field label="Бюджет на продукты"><Seg opts={[{ v: "эконом", l: "Эконом" }, { v: "средний", l: "Средний" }, { v: "гибкий", l: "Гибкий" }]} val={p.budget} set={(v: any) => up({ budget: v })} /></Field><Field label="Время на готовку"><Seg opts={[{ v: 15, l: "до 15 мин" }, { v: 30, l: "до 30 мин" }, { v: 60, l: "больше" }]} val={p.cookTime} set={(v: any) => up({ cookTime: v })} /></Field><Field label="Готовить заранее?"><Seg opts={[{ v: true, l: "Да, удобно" }, { v: false, l: "Нет" }]} val={p.prep} set={(v: any) => up({ prep: v })} /></Field><Btn cls="w-full" onClick={() => setStep(10)}>Дальше</Btn></div>,
    <div key="s10"><h2 className="text-xl font-bold mb-3">Какой формат питания выбираете?</h2>{[["keto", "🥑", "Кето", "Разнообразный рацион: мясо, овощи, сыр, десерты"], ["carnivore", "🥩", "Карнивор", "Максимально просто: продукты животного происхождения"], ["explore", "🔍", "Пока изучаю", "Сравню подходы и выберу позже"]].map(([v, e, t, dd]) => <button key={v} onClick={() => up({ mode: v })} className={`w-full flex items-center gap-3 px-4 py-3.5 rounded-2xl border mb-2 text-left ${p.mode === v ? "border-2" : "border-stone-200 dark:border-white/15"}`} style={p.mode === v ? { borderColor: "var(--acc)", background: "var(--accbg)" } : {}}><span className="text-2xl">{e}</span><span><b className="text-sm block">{t}</b><span className="text-xs text-stone-500">{dd}</span></span></button>)}<p className="text-[11px] text-stone-400 mb-3">Режим можно изменить в любой момент в настройках.</p><Btn cls="w-full" disabled={!p.mode} onClick={() => setStep(11)}>Дальше</Btn></div>,
    <div key="s11"><h2 className="text-xl font-bold mb-3">Ваш опыт такого питания</h2><Seg opts={[{ v: "нет", l: "Начинаю с нуля" }, { v: "пробовал", l: "Пробовал(а)" }, { v: "постоянно", l: "Питаюсь так давно" }]} val={p.exp} set={(v: any) => up({ exp: v })} /><Btn cls="w-full mt-4" disabled={!p.exp} onClick={() => setStep(12)}>Дальше</Btn></div>,
    <div key="s12"><h2 className="text-xl font-bold mb-3">Здоровье и лекарства</h2><Field label="Принимаете лекарства на постоянной основе?"><Seg opts={[{ v: true, l: "Да" }, { v: false, l: "Нет" }]} val={p.meds} set={(v: any) => up({ meds: v })} /></Field><Field label="Есть диагностированные заболевания?"><Seg opts={[{ v: true, l: "Да" }, { v: false, l: "Нет" }]} val={p.diseases} set={(v: any) => up({ diseases: v })} /></Field><div className="rounded-2xl bg-amber-50 dark:bg-amber-900/20 border border-amber-200 dark:border-amber-800 p-4 text-xs text-amber-900 dark:text-amber-200 leading-relaxed">⚠️ <b>Важно.</b> Людям с заболеваниями, беременным и кормящим, несовершеннолетним, людям с расстройствами пищевого поведения, а также принимающим сахароснижающие, гипотензивные и другие влияющие на обмен веществ препараты необходимо обсудить изменение рациона с врачом до начала.<br /><br />Приложение не ставит диагнозы, не отменяет лекарства и не заменяет медицинскую консультацию.</div><Btn cls="w-full mt-4" onClick={() => setStep(13)}>Дальше</Btn></div>,
    <div key="s13" className="text-center"><div className="text-6xl mb-4">🎉</div><h2 className="text-2xl font-bold mb-2">Всё готово, {p.name}!</h2><p className="text-sm text-stone-500 mb-5">Мы собрали стартовое меню, подобрали рецепты и подготовили первый список покупок.</p><Btn cls="w-full" onClick={() => { const m = p.mode === "carnivore" ? "carnivore" : "keto"; const menu = genMenu(m, 3, p.meals || 3); store.menu = menu; store.shopping = { items: shoppingItems(menu), checked: {} }; store.onboarded = true; checkAch(); emit(); go("#/home"); }}>Открыть моё меню →</Btn></div>];
  return <div className="min-h-screen flex items-center justify-center p-4" style={{ background: "var(--bg)" }}><div className="w-full max-w-md">{step > 0 && step < 13 && <div className="h-1.5 rounded-full bg-stone-200 dark:bg-white/10 mb-6"><div className="h-full rounded-full transition-all" style={{ width: step / 13 * 100 + "%", background: "var(--acc)" }} /></div>}<Card cls="p-6">{steps[step]}</Card></div></div>;
}

/* ================= 6. СТРАНИЦЫ ================= */
function HomePage() { const st = useStore(); const p = st.profile; const m = MODE(); const today = st.day; const menu = st.menu; const slot = menu?.days.find((d: any) => d.date === today); const diaryToday = st.diary[today]; const water = st.water[today] || 0; const tipIdx = new Date().getDate() % TIPS.length; const rec = RECIPES.filter(r => r.mode === (m === "explore" ? "keto" : m)); const sug = rec[Math.floor(Math.random() * rec.length)]; const reminders = reminderState().filter((r: any) => r.on); checkAch();
  return <div className="p-4 max-w-3xl mx-auto space-y-4">
    <div className="rounded-3xl p-6 text-white" style={{ background: "linear-gradient(135deg,var(--acc),var(--acc2))" }}><div className="text-xs opacity-80 mb-1">{new Date().toLocaleDateString("ru-RU", { weekday: "long", day: "numeric", month: "long" })}</div><h1 className="text-2xl font-bold mb-1">Привет, {p.name || "друг"}! 👋</h1><div className="text-sm opacity-90 mb-1">{MODE_INFO[m].emoji} Режим: <b>{MODE_INFO[m].title}</b> · <button className="underline" onClick={() => go("#/settings")}>изменить</button></div><p className="text-[13px] opacity-80 max-w-md">{st.homeTxt.sub}. Кето и карнивор без сложных расчётов, дорогих продуктов и отдельной кухни для всей семьи.</p></div>
    <div className="grid grid-cols-2 sm:grid-cols-4 gap-2">{[["🧩", "Собрать блюдо", "#/builder"], ["📅", "Меню", "#/menu"], ["🛒", "Покупки", "#/shopping"], ["📔", "Дневник", "#/diary"]].map(([e, t, l]) => <Card key={t} cls="p-3 text-center cursor-pointer hover:shadow-md transition" onClick={() => go(l)}><div className="text-2xl">{e}</div><div className="text-xs font-semibold mt-1">{t}</div></Card>)}</div>
    <Card cls="p-4"><div className="flex justify-between items-center mb-3"><h2 className="font-bold">План на сегодня</h2>{!slot && <button className="text-xs underline" style={{ color: "var(--acc)" }} onClick={() => go("#/menu")}>Собрать меню</button>}</div>
      {slot ? Object.entries(slot.slots).map(([cat, id]: any) => { const r = RECIPES.find(x => x.id === id)!; const done = st.doneDishes[today]?.includes(id); return <div key={id} className="flex items-center gap-3 py-2 border-b border-stone-100 dark:border-white/5 last:border-0"><span className="text-2xl">{r.emoji}</span><div className="flex-1"><div className="text-sm font-semibold">{r.title}</div><div className="text-[11px] text-stone-400">{CATR[cat]} · {r.time} мин · {r.kcal} ккал</div></div><button onClick={() => setSt(s => { const arr = s.doneDishes[today] || (s.doneDishes[today] = []); const i = arr.indexOf(id); i >= 0 ? arr.splice(i, 1) : arr.push(id); })} className={`w-7 h-7 rounded-full border-2 flex items-center justify-center text-sm ${done ? "text-white" : "text-transparent"}`} style={done ? { background: "var(--acc)", borderColor: "var(--acc)" } : { borderColor: "rgba(120,113,108,.3)" }}>✓</button></div>; }) : <Empty e="🍽️" t="На сегодня плана нет" d="Соберите меню — это займёт минуту." btn="Создать меню" onClick={() => go("#/menu")} />}</Card>
    <div className="grid sm:grid-cols-2 gap-4">
      <Card cls="p-4"><h3 className="font-bold text-sm mb-1">{diaryToday ? "Дневник заполнен ✅" : "Как вы себя чувствуете?"}</h3><p className="text-xs text-stone-500 mb-3">{diaryToday ? "Можно обновить отметки в любой момент." : "30 секунд — и мы увидим динамику за неделю."}</p><Btn variant={diaryToday ? "soft" : "primary"} onClick={() => go("#/diary")}>{diaryToday ? "Открыть дневник" : "Заполнить дневник"}</Btn></Card>
      <Card cls="p-4"><h3 className="font-bold text-sm mb-2">Вода</h3><p className="text-[11px] text-stone-400 mb-2">Без универсальной нормы — отмечайте, сколько выпили.</p><div className="flex gap-1.5 mb-2">{[1, 2, 3, 4, 5, 6, 7, 8].map(n => <button key={n} onClick={() => setSt(s => { s.water[today] = water === n ? n - 1 : n; })} className={`w-8 h-9 rounded-lg text-sm ${n <= water ? "" : "opacity-25 grayscale"}`}>💧</button>)}</div><div className="text-xs text-stone-500">{water > 0 ? water + " стакан(ов)" : ""}</div></Card>
    </div>
    <Card cls="p-4"><h2 className="font-bold mb-3">Что приготовить сегодня? 🍳</h2><div className="flex gap-4 items-center cursor-pointer" onClick={() => go("#/recipe/" + sug.id)}><div className="w-20 h-20 rounded-2xl flex-shrink-0 flex items-center justify-center text-4xl" style={{ background: `linear-gradient(135deg,${sug.g[0]},${sug.g[1]})` }}>{sug.emoji}</div><div><div className="font-semibold text-sm">{sug.title}</div><div className="text-xs text-stone-500 mt-1">⏱ {sug.time} мин · {sug.kcal} ккал · {sug.mode === "keto" ? "нетто " + sug.nc + " г" : "белок " + sug.p + " г"}</div><div className="text-xs mt-1 underline" style={{ color: "var(--acc)" }}>Смотреть рецепт →</div></div></div></Card>
    <Card cls="p-4"><h2 className="font-bold mb-3">Прогресс за неделю</h2><div className="grid grid-cols-4 gap-2"><Stat e="📔" v={Object.keys(st.diary).length} l="дн. дневника" /><Stat e="🍳" v={Object.keys(st.cooked).length} l="блюд" /><Stat e="❤️" v={Object.keys(st.fav).length} l="избранных" /><Stat e="🏅" v={Object.keys(st.ach).length} l="достижений" /></div></Card>
    {reminders.length > 0 && <Card cls="p-4"><div className="flex justify-between items-center mb-2"><h2 className="font-bold text-sm">Ближайшие напоминания</h2><button className="text-xs underline" onClick={() => go("#/reminders")}>настроить</button></div><div className="flex gap-2 overflow-x-auto">{reminders.map((r: any) => <span key={r.id} className="text-[11px] px-2.5 py-1.5 rounded-full bg-stone-100 dark:bg-white/10 whitespace-nowrap">{r.ic} {r.t}</span>)}</div></Card>}
    <Card cls="p-4"><div className="flex gap-3"><span className="text-2xl">💡</span><div><div className="text-xs font-bold uppercase tracking-wide text-stone-400 mb-1">Совет дня</div><div className="text-sm">{TIPS[tipIdx]}</div></div></div></Card>
    <Card cls="p-4"><div className="flex gap-3 items-start"><div className="w-11 h-11 rounded-full flex items-center justify-center text-xl flex-shrink-0" style={{ background: "var(--accbg)" }}>👩‍⚕️</div><div><div className="text-xs font-bold uppercase tracking-wide text-stone-400 mb-1">Сообщение от нутрициолога</div><p className="text-sm text-stone-600 dark:text-stone-300">Первые недели — время адаптации. Не требуйте от себя идеальности: достаточно замечать, как меняется самочувствие, и есть достаточно. Если появятся вопросы — я на связи.</p><button className="text-xs font-semibold underline mt-2" style={{ color: "var(--acc)" }} onClick={() => go("#/nutritionist")}>Написать Марии →</button></div></div></Card>
  </div>;
}

const FILTERS: [string, string, (r: Recipe) => boolean][] = [["quick", "Быстро · до 15 мин", r => r.time <= 15], ["cheap", "Бюджетно", r => r.cost === 1], ["nodairy", "Без молочных", r => !r.ing.some(([n]) => ["Сыр твёрдый", "Сливки 33%", "Сметана", "Творог 5%", "Сливочное масло", "Моцарелла"].includes(n))], ["noegg", "Без яиц", r => !r.ing.some(([n]) => n.includes("Яйца"))], ["family", "Для всей семьи", r => r.fam], ["freeze", "Можно заморозить", r => r.freeze], ["batch", "На несколько дней", r => r.batch], ["keto", "Кето", r => r.mode === "keto"], ["carnivore", "Карнивор", r => r.mode === "carnivore"]];
function RecipeCard({ r }: any) { const st = useStore(); const fav = !!st.fav[r.id]; const locked = r.mode === MODE() && !st.premium && !isFree(r);
  return <Card cls="overflow-hidden" onClick={() => go("#/recipe/" + r.id)}><div className="cursor-pointer"><FoodPic r={r} /><div className="p-3"><div className="flex gap-1 mb-1"><span className="text-[10px] px-2 py-0.5 rounded-full font-semibold" style={{ background: "var(--accbg)", color: "var(--acc)" }}>{r.mode === "keto" ? "Кето" : "Карнивор"}</span><span className="text-[10px] px-2 py-0.5 rounded-full bg-stone-100 dark:bg-white/10 text-stone-500">{CATR[r.cat]}</span></div><div className="font-semibold text-sm leading-snug mb-1.5">{r.title}</div><div className="flex items-center justify-between text-xs text-stone-500"><span>⏱ {r.time} мин · {r.kcal} ккал</span><span className="font-bold" style={{ color: "var(--acc)" }}>{r.mode === "keto" ? "нетто " + r.nc + " г" : "Б " + r.p + " г"}</span></div><div className="flex justify-between items-center mt-2"><Stars c={r.cost} /><button onClick={(e: any) => { e.stopPropagation(); setSt(s => { if (s.fav[r.id]) delete s.fav[r.id]; else s.fav[r.id] = true; }); checkAch(); emit(); }} className={`text-lg ${fav ? "" : "opacity-30"}`}>❤️</button></div>{locked && <div className="text-[10px] text-stone-400 mt-1">🔒 Доступно в Premium · <button className="underline" onClick={(e: any) => { e.stopPropagation(); go("#/premium"); }}>подробнее</button></div>}</div></div></Card>; }
function RecipesPage() { const [fl, setFl] = useState(new Set<string>()); const [q, setQ] = useState(""); const [mode, setMode] = useState("all"); const [cat, setCat] = useState("all"); const [load, setLoad] = useState(true); useEffect(() => { const t = setTimeout(() => setLoad(false), 450); return () => clearTimeout(t); }, []);
  const list = RECIPES.filter(r => (mode === "all" || r.mode === mode) && (cat === "all" || r.cat === cat) && (!q || r.title.toLowerCase().includes(q.toLowerCase())) && [...fl].every(f => FILTERS.find(x => x[0] === f)![2](r)));
  return <div className="p-4 max-w-6xl mx-auto"><h1 className="text-2xl font-bold mb-1">Рецепты</h1><p className="text-sm text-stone-500 mb-4">{RECIPES.filter(r => r.mode === "keto").length} кето · {RECIPES.filter(r => r.mode === "carnivore").length} карнивор</p><Input placeholder="🔍 Найти рецепт…" value={q} onChange={(e: any) => setQ(e.target.value)} cls="mb-3" /><div className="flex gap-2 mb-3 overflow-x-auto pb-1">{[["all", "Все"], ["keto", "🥑 Кето"], ["carnivore", "🥩 Карнивор"]].map(([v, l]) => <Chip key={v} on={mode === v} onClick={() => setMode(v)}>{l}</Chip>)}<span className="w-2" />{["breakfast", "lunch", "dinner", "snack", "dessert", "prep"].map(c => <Chip key={c} on={cat === c} onClick={() => setCat(cat === c ? "all" : c)}>{CATR[c]}</Chip>)}</div><div className="flex gap-2 overflow-x-auto pb-2 mb-3">{FILTERS.map(([id, l]) => <Chip key={id} on={fl.has(id)} onClick={() => { const s = new Set(fl); s.has(id) ? s.delete(id) : s.add(id); setFl(s); }}>{l}</Chip>)}</div>
    {load ? <div className="text-center py-16 text-stone-400"><div className="animate-pulse text-4xl mb-2">🍽️</div>Загружаем рецепты…</div> : list.length === 0 ? <Empty e="🍳" t="Ничего не нашлось" d="Попробуйте убрать часть фильтров." btn="Сбросить фильтры" onClick={() => { setFl(new Set()); setQ(""); setMode("all"); setCat("all"); }} /> : <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-4">{list.map(r => <RecipeCard key={r.id} r={r} />)}</div>}</div>; }

function RecipePage({ id }: any) { const st = useStore(); const r = RECIPES.find(x => x.id === id); const [toast, setToast] = useState(""); if (!r) return <Empty e="🥲" t="Рецепт не найден" btn="К рецептам" onClick={() => go("#/recipes")} />; const fav = !!st.fav[r.id];
  const addShop = () => { const items = r.ing.filter(([n]) => !store.hasItems.includes(n)).map(([n, a]: any) => ({ id: uid(), name: n, qty: ingAmount(a), unit: a.replace(/[\d.,\s]+/, "").trim() || "шт", cost: ingAmount(a) * (FOODS.find(f => f[0] === n)?.[2] || 0) / 10, custom: false })); setSt(s => { s.shopping.items.push(...items); }); checkAch(); emit(); setToast("Ингредиенты добавлены в список покупок 🛒"); };
  return <div className="max-w-3xl mx-auto p-4"><button onClick={() => history.back()} className="text-sm text-stone-500 mb-3">← Назад</button><FoodPic r={r} big />
    <div className="flex items-start justify-between mt-4"><div><h1 className="text-2xl font-bold leading-tight">{r.title}</h1><div className="flex gap-1.5 mt-2 flex-wrap"><span className="text-[11px] px-2 py-1 rounded-full font-semibold" style={{ background: "var(--accbg)", color: "var(--acc)" }}>{r.mode === "keto" ? "🥑 Кето" : "🥩 Карнивор"}</span><span className="text-[11px] px-2 py-1 rounded-full bg-stone-100 dark:bg-white/10">{CATR[r.cat]}</span><Lvl n={r.diff} />{r.make && <span className="text-[11px] px-2 py-1 rounded-full bg-stone-100 dark:bg-white/10">✅ можно заранее</span>}</div></div><button onClick={() => { setSt(s => { if (s.fav[r.id]) delete s.fav[r.id]; else s.fav[r.id] = true; }); checkAch(); emit(); }} className="text-3xl">{fav ? "❤️" : "🤍"}</button></div>
    <div className="grid grid-cols-4 gap-2 my-4">{[["⏱", r.time + " мин", "время"], ["🍽", String(r.serv), "порций"], ["🔥", String(r.kcal), "ккал/порц."], [COST[r.cost], r.cost === 1 ? "бюджетно" : r.cost === 2 ? "средне" : "дороже", "цена"]].map(([e, v, l]) => <Card key={l} cls="p-3 text-center"><div className="text-lg">{e}</div><div className="font-bold text-sm">{v}</div><div className="text-[10px] text-stone-400">{l}</div></Card>)}</div>
    <Card cls="p-4 mb-4"><div className="grid grid-cols-4 text-center text-sm">{[["Белки", r.p + " г"], ["Жиры", r.f + " г"], ["Углеводы", r.mode === "keto" ? ((r.kcal - r.p * 4 - r.f * 9) / 4).toFixed(0) + " г" : "мин."], ["Нетто", r.nc + " г"]].map(([l, v]) => <div key={l}><div className="font-bold" style={{ color: "var(--acc)" }}>{v}</div><div className="text-[10px] text-stone-400">{l}</div></div>)}</div>{r.mode === "keto" && <div className="text-[11px] text-stone-400 mt-2 text-center">Чистые углеводы ≈ общие минус клетчатка. Значение ориентировочное.</div>}</Card>
    <Card cls="p-4 mb-4"><h3 className="font-bold mb-3">Ингредиенты</h3>{r.ing.map(([n, a]) => <div key={n} className="flex justify-between py-1.5 border-b border-stone-100 dark:border-white/5 last:border-0 text-sm"><span>{n}</span><span className="text-stone-500">{a}</span></div>)}{Object.keys(r.subs).length > 0 && <details className="mt-3"><summary className="text-sm font-semibold cursor-pointer" style={{ color: "var(--acc)" }}>🔄 Возможные замены</summary><div className="mt-2 space-y-1 text-xs text-stone-500">{Object.entries(r.subs).map(([a, b]) => <div key={a} className="flex justify-between gap-2"><span>{a} →</span><b>{b}</b></div>)}</div></details>}</Card>
    <Card cls="p-4 mb-4"><h3 className="font-bold mb-3">Приготовление</h3>{r.steps.map((s0: string, i: number) => <div key={i} className="flex gap-3 mb-3"><span className="w-6 h-6 rounded-full flex-shrink-0 flex items-center justify-center text-xs font-bold text-white" style={{ background: "var(--acc)" }}>{i + 1}</span><span className="text-sm">{s0}</span></div>)}</Card>
    <Card cls="p-4 mb-4 text-sm"><div className="grid sm:grid-cols-2 gap-3"><div>🧊 <b>Хранение:</b> {r.store}</div><div>👨‍👩‍👧 {r.fam ? "Подходит всей семье — добавьте привычный гарнир отдельно." : "Индивидуальное блюдо."}</div>{r.freeze && <div>❄️ Можно замораживать</div>}{r.batch && <div>📦 Удобно на несколько дней</div>}</div></Card>
    <div className="grid grid-cols-2 gap-3 mb-8"><Btn onClick={addShop} variant="soft">🛒 В список покупок</Btn><Btn onClick={() => { setSt(s => { s.cooked[r.id] = Date.now(); }); checkAch(); emit(); setToast("Отмечено! Приятного аппетита 🍳"); }} variant={st.cooked[r.id] ? "primary" : "ghost"}>{st.cooked[r.id] ? "✅ Приготовлено" : "🍳 Отметить готовку"}</Btn></div>
    {toast && <Toast msg={toast} onClose={() => setToast("")} />}</div>; }

function BuilderPage() { const st = useStore(); const m = MODE(); const sel = new Set<string>(st.pantry); const [toast, setToast] = useState("");
  const toggle = (n: string) => setSt(s => { if (s.pantry.includes(n)) s.pantry = s.pantry.filter((x: string) => x !== n); else s.pantry.push(n); });
  const list = RECIPES.filter(r => m === "explore" ? true : r.mode === m).map(r => { const have = r.ing.filter(([n]) => sel.has(n)).map(([n]) => n); const miss = r.ing.map(([n]) => n).filter(n => !have.includes(n)); return { r, have, miss }; }).filter(x => x.have.length >= 1 && x.miss.length <= 3).sort((a, b) => b.have.length - a.have.length).slice(0, 6);
  return <div className="p-4 max-w-3xl mx-auto"><h1 className="text-2xl font-bold mb-1">Собрать блюдо 🧩</h1><p className="text-sm text-stone-500 mb-4">Отметьте продукты дома ({MODE_INFO[m].title.toLowerCase()}) — предложу блюда.</p>
    <div className="space-y-3 mb-6">{Object.entries(CATS).filter(([id]) => FOODS.some(f => f[1] === id)).map(([id, name]) => <div key={id}><div className="text-xs font-bold uppercase tracking-wide text-stone-400 mb-1.5">{name}</div><div className="flex flex-wrap gap-1.5">{FOODS.filter(f => f[1] === id).map(([n]) => { const on = sel.has(n); return <button key={n} onClick={() => toggle(n)} className={`px-2.5 py-1.5 rounded-lg text-xs font-medium border ${on ? "text-white border-transparent" : "bg-white dark:bg-white/5 border-stone-200 dark:border-white/15"}`} style={on ? { background: "var(--acc)" } : {}}>{n}</button>; })}</div></div>)}</div>
    <h2 className="font-bold mb-3">Что можно приготовить {sel.size > 0 && `(${sel.size})`}</h2>
    {sel.size === 0 ? <Empty e="🧺" t="Пока пусто" d="Отметьте продукты выше — появятся идеи." /> : list.length === 0 ? <Empty e="🤔" t="Точных совпадений нет" d="Безопасная комбинация: белок + жир для готовки + соль. Или добавьте продукты."><Btn onClick={() => go("#/recipes")}>К рецептам</Btn></Empty> : list.map(({ r, have, miss }) => <Card key={r.id} cls="p-4 mb-3"><div className="flex gap-3"><div className="w-16 h-16 rounded-xl flex-shrink-0 flex items-center justify-center text-3xl" style={{ background: `linear-gradient(135deg,${r.g[0]},${r.g[1]})` }}>{r.emoji}</div><div className="flex-1"><div className="font-semibold text-sm">{r.title}</div><div className="text-[11px] text-stone-500 mt-0.5">⏱ {r.time} мин · {r.kcal} ккал · Б {r.p} / Ж {r.f} / {r.mode === "keto" ? "нетто " + r.nc : "мин. углеводов"}</div><div className="text-[11px] mt-1.5">✅ Есть: {have.join(", ")}</div>{miss.length > 0 && <div className="text-[11px] text-stone-500">🧾 Не хватает: {miss.join(", ")} · <button className="underline" style={{ color: "var(--acc)" }} onClick={() => { setSt(s => { miss.forEach(n => { if (!s.shopping.items.find((i: any) => i.name === n)) s.shopping.items.push({ id: uid(), name: n, qty: 1, unit: "шт", cost: (FOODS.find(f => f[0] === n)?.[2] || 0) / 10, custom: false }); }); }); emit(); setToast("Недостающее — в списке покупок"); }}>в список</button></div>}<div className="flex gap-2 mt-2"><Btn cls="!py-1.5 !px-3 !text-xs" onClick={() => go("#/recipe/" + r.id)}>Рецепт</Btn>{st.menu && <Btn variant="soft" cls="!py-1.5 !px-3 !text-xs" onClick={() => { const d = st.menu.days.find((x: any) => x.date === st.day) || st.menu.days[0]; d.slots[r.cat] = r.id; emit(); setToast("Добавлено в меню на " + fmtRus(d.date)); }}>В меню</Btn>}</div></div></div></Card>)}
    {toast && <Toast msg={toast} onClose={() => setToast("")} />}</div>; }

function MenuPage() { const st = useStore(); const m = MODE(); const menu = st.menu; const [period, setPeriod] = useState(menu ? menu.days.length : 3); const [loading, setLoading] = useState(false); const [toast, setToast] = useState("");
  const gen = () => { setLoading(true); setTimeout(() => { setSt(s => { s.menu = genMenu(m === "explore" ? "keto" : m, period, P().meals || 3); }); checkAch(); emit(); setLoading(false); }, 600); };
  if (!menu) return <div className="p-4 max-w-3xl mx-auto"><h1 className="text-2xl font-bold mb-1">Персональное меню 📅</h1><Card cls="p-6 my-4"><p className="text-sm text-stone-500 mb-4">Учтём режим ({MODE_INFO[m].title}), аллергии, нелюбимые продукты, бюджет и время. Калорийность не навязываем — порции меняются вручную.</p><Field label="На сколько дней?"><div className="flex gap-2">{[1, 3, 7].map(d => <button key={d} onClick={() => setPeriod(d)} className={`flex-1 py-3 rounded-xl border font-bold ${period === d ? "text-white border-transparent" : "border-stone-200 dark:border-white/15"}`} style={period === d ? { background: "var(--acc)" } : {}}>{d} {d === 1 ? "день" : d < 5 ? "дня" : "дней"}</button>)}</div></Field><Btn cls="w-full" onClick={gen} disabled={loading}>{loading ? "Собираем меню…" : "Собрать меню"}</Btn></Card><h2 className="font-bold mb-3">Готовые программы</h2><div className="grid sm:grid-cols-2 gap-3">{PROGRAMS.map(pr => <Card key={pr.id} cls="p-4 cursor-pointer hover:shadow-md transition" onClick={() => go("#/programs")}><div className="flex items-center gap-3 mb-1"><span className="text-2xl">{pr.emoji}</span><b className="text-sm">{pr.title}</b></div><div className="text-xs text-stone-500">{pr.desc}</div><div className="mt-2">{pr.price === "free" ? <span className="text-[10px] px-2 py-0.5 rounded-full bg-emerald-100 text-emerald-700 dark:bg-emerald-900/40 dark:text-emerald-300 font-bold">бесплатно</span> : <span className="text-[10px] px-2 py-0.5 rounded-full font-bold" style={{ background: "var(--accbg)", color: "var(--acc)" }}>premium</span>}</div></Card>)}</div></div>;
  const ings: any[] = menuIng(menu); const total = ings.reduce((s, i) => s + i.cost, 0);
  return <div className="p-4 max-w-3xl mx-auto"><div className="flex justify-between items-center mb-3"><h1 className="text-2xl font-bold">Меню</h1><button className="text-xs underline" style={{ color: "var(--acc)" }} onClick={gen}>🔄 Пересобрать</button></div>
    <Card cls="p-3 mb-4 flex items-center justify-between flex-wrap gap-2"><div className="text-sm"><b>{menu.days.length} {menu.days.length === 1 ? "день" : menu.days.length < 5 ? "дня" : "дней"}</b> · {menu.mode === "keto" ? "🥑 кето" : "🥩 карнивор"}</div><div className="flex items-center gap-2 text-sm">Порции: <button className="w-7 h-7 rounded-full bg-black/5 dark:bg-white/10 font-bold" onClick={() => { menu.portion = Math.max(1, menu.portion - 1); emit(); }}>−</button><b>{menu.portion}</b><button className="w-7 h-7 rounded-full bg-black/5 dark:bg-white/10 font-bold" onClick={() => { menu.portion++; emit(); }}>+</button></div></Card>
    {menu.days.map((d: any, di: number) => <Card key={d.date} cls="p-4 mb-3"><div className="font-bold text-sm mb-2 capitalize">{fmtRus(d.date)} {di === 0 && <span className="text-[10px] px-2 py-0.5 rounded-full ml-1 text-white" style={{ background: "var(--acc)" }}>сегодня</span>}</div>{Object.entries(d.slots).map(([cat, id]: any) => { const r = RECIPES.find(x => x.id === id)!; return <div key={cat} className="flex items-center gap-3 py-2 border-b border-stone-100 dark:border-white/5 last:border-0"><span className="text-2xl">{r.emoji}</span><div className="flex-1 min-w-0"><div className="text-sm font-semibold truncate">{r.title}</div><div className="text-[11px] text-stone-400">{CATR[cat]} · {r.time} мин</div></div><button title="Заменить" onClick={() => { const pool2 = RECIPES.filter(x => x.mode === menu.mode && x.cat === cat && !Object.values(d.slots).includes(x.id)); const alt = pool2[Math.floor(Math.random() * pool2.length)]; if (alt) d.slots[cat] = alt.id; emit(); }} className="w-8 h-8 rounded-full bg-black/5 dark:bg-white/10 text-sm">🔄</button><button title="Убрать" onClick={() => { delete d.slots[cat]; emit(); }} className="w-8 h-8 rounded-full bg-black/5 dark:bg-white/10 text-sm">✕</button></div>; })}{Object.keys(d.slots).length === 0 && <div className="text-xs text-stone-400 py-2">Блюд нет — добавьте из рецептов.</div>}</Card>)}
    <Card cls="p-4 mb-4"><h3 className="font-bold text-sm mb-2">Ингредиенты ({ings.length})</h3><div className="max-h-44 overflow-y-auto text-xs">{ings.map(i => <div key={i.name} className="flex justify-between py-1 border-b border-stone-100 dark:border-white/5"><span>{i.name}</span><span className="text-stone-400">{i.qty.toFixed(1)} {i.unit}</span></div>)}</div><div className="flex justify-between text-sm font-bold mt-3"><span>Ориентировочная стоимость</span><span style={{ color: "var(--acc)" }}>≈ {Math.round(total)} ₽</span></div><div className="text-[10px] text-stone-400 mt-1">Цены условные, зависят от региона и магазина.</div></Card>
    <div className="grid grid-cols-2 gap-2 mb-6"><Btn onClick={() => { setSt(s => { s.shopping.items = shoppingItems(s.menu); s.shopping.checked = {}; }); checkAch(); emit(); go("#/shopping"); }}>🛒 Список покупок</Btn><Btn variant="soft" onClick={() => { menu.saved = true; emit(); setToast("Меню сохранено ✅"); }}>💾 Сохранить</Btn><Btn variant="soft" onClick={() => window.print()}>🖨 Печать / PDF</Btn><Btn variant="soft" onClick={() => go("#/nutritionist")}>💬 Нутрициологу</Btn></div>
    {toast && <Toast msg={toast} onClose={() => setToast("")} />}</div>; }

function ShoppingPage() { const st = useStore(); const items = st.shopping.items; const [budget, setBudget] = useState(false); const [newItem, setNewItem] = useState(""); const [toast, setToast] = useState("");
  const groups: any = {}; items.forEach((i: any) => { const cat = FOODS.find(f => f[0] === i.name)?.[1] || "other"; (groups[cat] || (groups[cat] = [])).push(i); });
  const total = items.reduce((s: number, i: any) => s + (i.cost || 0), 0);
  const add = () => { if (!newItem.trim()) return; setSt(s => { s.shopping.items.push({ id: uid(), name: newItem.trim(), qty: 1, unit: "шт", cost: 0, custom: true }); }); setNewItem(""); };
  if (!st.menu && items.length === 0) return <Empty e="🛒" t="Список пуст" d="Соберите меню — список появится автоматически. Или добавьте продукты вручную." btn="К меню" onClick={() => go("#/menu")} />;
  return <div className="p-4 max-w-3xl mx-auto"><div className="flex justify-between items-center mb-1"><h1 className="text-2xl font-bold">Список покупок</h1>{items.length > 0 && <button className="text-xs underline" style={{ color: "var(--acc)" }} onClick={() => { navigator.share?.({ text: items.map((i: any) => `• ${i.name} — ${i.qty.toFixed(1)} ${i.unit}`).join("\n") }).catch(() => { }); setToast("Список готов к отправке"); }}>Поделиться</button>}</div>
    <div className="text-xs text-stone-400 mb-3">Одинаковые продукты объединены. Что уже есть дома: <button className="underline" onClick={() => go("#/fridge")}>Мой холодильник</button></div>
    <div className="flex gap-2 mb-4"><Input placeholder="Добавить свой продукт…" value={newItem} onChange={(e: any) => setNewItem(e.target.value)} onKeyDown={(e: any) => e.key === "Enter" && add()} /><Btn onClick={add}>＋</Btn></div>
    <div className="flex items-center justify-between mb-4"><Toggle on={budget} set={setBudget} label="Режим «бюджетная корзина»" /><span className="text-sm font-bold" style={{ color: "var(--acc)" }}>≈ {Math.round(total)} ₽</span></div>
    {budget && <Card cls="p-3 mb-4 text-xs"><b>💰 Бюджетная корзина.</b> Замените дорогие позиции: сёмга → горбуша/скумбрия, стейк → фарш или тушёная говядина. Сезонные продукты: капуста, кабачок, огурцы, зелень.</Card>}
    {Object.entries(groups).map(([cat, list0]: any) => <div key={cat} className="mb-4"><div className="text-xs font-bold uppercase tracking-wide text-stone-400 mb-2">{CATS[cat] || "Другое"}</div>{list0.map((i: any) => <div key={i.id} className={`flex items-center gap-3 py-2.5 border-b border-stone-100 dark:border-white/5 ${st.shopping.checked[i.id] ? "opacity-40" : ""}`}><button onClick={() => setSt(s => { s.shopping.checked[i.id] = !s.shopping.checked[i.id]; })} className={`w-6 h-6 rounded-lg border-2 flex items-center justify-center text-xs flex-shrink-0 ${st.shopping.checked[i.id] ? "text-white" : ""}`} style={st.shopping.checked[i.id] ? { background: "var(--acc)", borderColor: "var(--acc)" } : { borderColor: "rgba(120,113,108,.3)" }}>✓</button><span className={`flex-1 text-sm ${st.shopping.checked[i.id] ? "line-through" : ""}`}>{i.name}</span><span className="text-xs text-stone-400">{i.qty.toFixed(1)} {i.unit}</span>{i.cost > 0 && <span className="text-xs font-semibold" style={{ color: "var(--acc)" }}>{Math.round(i.cost)} ₽</span>}{budget && i.cost > 15 && <span title="Дорогая позиция">💎</span>}<button onClick={() => setSt(s => { s.shopping.items = s.shopping.items.filter((x: any) => x.id !== i.id); })} className="text-stone-300 hover:text-red-400">✕</button></div>)}</div>)}
    {items.length > 0 && <div className="text-xs text-stone-400 mb-6">{Object.keys(st.shopping.checked).filter(k => st.shopping.checked[k]).length} из {items.length} куплено</div>}
    {toast && <Toast msg={toast} onClose={() => setToast("")} />}</div>; }

function FridgePage() { const st = useStore(); const [add, setAdd] = useState(""); const [days, setDays] = useState(3);
  const addF = () => { if (!add.trim()) return; setSt(s => { s.pantry.push(add.trim()); }); setAdd(""); };
  const suggestions = RECIPES.filter(r => r.mode === (MODE() === "explore" ? "keto" : MODE())).map(r => ({ r, n: r.ing.filter(([n]) => st.pantry.includes(n)).length })).filter(x => x.n >= 2).sort((a, b) => b.n - a.n).slice(0, 3);
  return <div className="p-4 max-w-3xl mx-auto"><h1 className="text-2xl font-bold mb-1">Мой холодильник 🧊</h1><p className="text-sm text-stone-500 mb-4">Отмечайте продукты дома — подскажем рецепты и не дадим ничего испортить.</p>
    <div className="flex gap-2 mb-4"><Input placeholder="Добавить продукт…" value={add} onChange={(e: any) => setAdd(e.target.value)} onKeyDown={(e: any) => e.key === "Enter" && addF()} /><Btn onClick={addF}>＋</Btn></div>
    {st.pantry.length === 0 ? <Empty e="🥚" t="Пока пусто" d="Добавьте продукты, которые есть дома." /> : <div><div className="flex flex-wrap gap-2 mb-5">{st.pantry.map((n: string) => <span key={n} className="px-3 py-1.5 rounded-full bg-white dark:bg-white/5 border border-stone-200 dark:border-white/15 text-sm flex items-center gap-2">{n}<button className="text-stone-300" onClick={() => setSt(s => { s.pantry = s.pantry.filter((x: string) => x !== n); })}>✕</button></span>)}</div>
      <Card cls="p-4 mb-4"><h3 className="font-bold text-sm mb-2">⏰ Срок хранения</h3><p className="text-xs text-stone-500 mb-2">Напомнить через: <b>{days} дн.</b></p><input type="range" min="1" max="7" value={days} onChange={(e: any) => setDays(+e.target.value)} className="w-full" style={{ accentColor: "var(--acc)" }} /><p className="text-xs mt-2">Безопасные ориентиры: готовое мясо/птица — 2–3 дня, готовая рыба — 1–2 дня, бульон — до 4 дней, яйца вкрутую — до недели.</p></Card>
      {suggestions.length > 0 && <div><h3 className="font-bold mb-2">Что приготовить из того, что есть</h3>{suggestions.map(({ r, n }) => <Card key={r.id} cls="p-3 mb-2 flex items-center gap-3 cursor-pointer" onClick={() => go("#/recipe/" + r.id)}><span className="text-2xl">{r.emoji}</span><div className="flex-1"><div className="text-sm font-semibold">{r.title}</div><div className="text-[11px] text-stone-400">{n} из {r.ing.length} продуктов уже дома</div></div><span style={{ color: "var(--acc)" }}>→</span></Card>)}</div>}</div>}</div>; }

function DiaryPage() { const st = useStore(); const day = st.day; const d: any = { energy: 3, hunger: 3, craving: 3, mood: 3, sleep: 3, digestion: 3, symp: [], cycle: null, note: "", ...(st.diary[day] || {}) };
  const up = (patch: any) => setSt(s => { s.diary[day] = { ...(s.diary[day] || {}), ...patch }; });
  const redFlag = d.symp.some((s0: string) => RED_FLAGS.includes(s0)); const insights = diaryInsights();
  return <div className="p-4 max-w-2xl mx-auto"><h1 className="text-2xl font-bold mb-1">Дневник самочувствия 📔</h1>
    <div className="flex gap-2 overflow-x-auto mb-4">{Array.from({ length: 7 }, (_, i) => dayISO(addDays(i - 6))).map(dt => <button key={dt} onClick={() => setSt(s => { s.day = dt; })} className={`px-3 py-2 rounded-xl text-xs font-semibold capitalize whitespace-nowrap border ${day === dt ? "text-white border-transparent" : "border-stone-200 dark:border-white/15"}`} style={day === dt ? { background: "var(--acc)" } : {}}>{fmtRus(dt)}{st.diary[dt] ? " ✓" : ""}</button>)}</div>
    {redFlag ? <div className="rounded-2xl bg-red-50 dark:bg-red-950/40 border-2 border-red-300 p-5 mb-4"><div className="font-bold text-red-700 dark:text-red-300 mb-2">🚨 Похоже, вам нужна медицинская помощь</div><p className="text-sm text-red-800 dark:text-red-200 mb-3">Отмеченные симптомы могут быть серьёзными. Приложение не может продолжать давать рекомендации по питанию.</p><Btn variant="danger" onClick={() => go("#/medical")}>Что делать прямо сейчас</Btn></div> : <Card cls="p-4 mb-4 space-y-4">{[["energy", "Энергия", "мало", "много"], ["hunger", "Голод", "сыт(а)", "очень голоден(на)"], ["craving", "Тяга к сладкому", "нет", "сильная"], ["mood", "Настроение", "плохое", "отличное"], ["sleep", "Качество сна", "плохой", "выспался(ась)"], ["digestion", "Пищеварение", "тяжело", "комфортно"]].map(([k, l, a, b]) => <div key={k}><div className="text-sm font-semibold mb-1.5">{l}</div><Scale val={d[k]} set={(v: any) => up({ [k]: v })} low={a} high={b} /></div>)}
      <div><div className="text-sm font-semibold mb-1.5">Симптомы (если есть)</div><div className="flex flex-wrap gap-1.5">{SYMP.map(s0 => { const on = d.symp.includes(s0); return <Chip key={s0} on={on} onClick={() => up({ symp: on ? d.symp.filter((x: string) => x !== s0) : [...d.symp, s0] })}>{s0}</Chip>; })}</div></div>
      <details className="text-sm"><summary className="font-semibold cursor-pointer">Ещё отметки (по желанию)</summary><div className="mt-3 space-y-3"><div><div className="text-sm font-semibold mb-1.5">Переносимость тренировок</div><Scale val={d.workout || 3} set={(v: any) => up({ workout: v })} low="тяжело" high="отлично" /></div><div><div className="text-sm font-semibold mb-1.5">Стресс</div><Scale val={d.stress || 3} set={(v: any) => up({ stress: v })} low="высокий" high="низкий" /></div><div><div className="text-sm font-semibold mb-1.5">Менструальный цикл (по желанию)</div><Seg opts={[{ v: "нет", l: "Не отмечаю" }, { v: "обычные", l: "Обычные дни" }, { v: "кд", l: "КД" }]} val={d.cycle} set={(v: any) => up({ cycle: v })} /></div></div></details>
      <Field label="Комментарий"><textarea value={d.note} onChange={(e: any) => up({ note: e.target.value })} rows={2} className="w-full px-3.5 py-2.5 rounded-xl border border-stone-200 dark:border-white/15 bg-white dark:bg-white/5 text-sm outline-none" placeholder="Как прошёл день?" /></Field>
      <Btn cls="w-full" onClick={() => { checkAch(); emit(); go("#/stats"); }}>Сохранить и смотреть динамику →</Btn></Card>}
    {!redFlag && d.craving >= 4 && <Card cls="p-4 mb-4"><div className="flex justify-between items-center"><div><b className="text-sm">Сильная тяга к сладкому? 🍬</b><div className="text-xs text-stone-500">Откройте «Антисрыв» — мягкий план без чувства вины.</div></div><Btn variant="soft" onClick={() => go("#/antisryv")}>Открыть</Btn></div></Card>}
    {!redFlag && insights.length > 0 && <div className="space-y-2 mb-4">{insights.map((i, ix) => <div key={ix} className={`rounded-xl p-3 text-sm ${i.tone === "warn" ? "bg-amber-50 dark:bg-amber-900/20 text-amber-900 dark:text-amber-200" : i.tone === "good" ? "bg-emerald-50 dark:bg-emerald-900/20 text-emerald-800 dark:text-emerald-200" : "bg-stone-100 dark:bg-white/5"}`}>{i.tone === "warn" ? "⚠️ " : ""}{i.t}</div>)}</div>}
    {!redFlag && d.symp.length >= 3 && <div className="rounded-xl bg-amber-50 dark:bg-amber-900/20 p-3 text-xs text-amber-900 dark:text-amber-200 mb-4">Несколько симптомов за день. Если они повторяются или усиливаются — обсудите самочувствие с врачом.</div>}</div>; }

function StatsPage() { const st = useStore(); const days = Array.from({ length: 14 }, (_, i) => dayISO(addDays(i - 13))); const vals = (k: string) => days.map(d => st.diary[d]?.[k]).filter((v: any) => v != null);
  return <div className="p-4 max-w-2xl mx-auto"><h1 className="text-2xl font-bold mb-4">Динамика 📈</h1>{Object.keys(st.diary).length === 0 ? <Empty e="📊" t="Данных пока нет" d="Заполняйте дневник — появятся графики за две недели." btn="К дневнику" onClick={() => go("#/diary")} /> : <div className="grid sm:grid-cols-2 gap-4 mb-4">{[["energy", "Энергия"], ["sleep", "Сон"], ["craving", "Тяга к сладкому"], ["mood", "Настроение"]].map(([k, l]) => <Card key={k} cls="p-4"><div className="text-sm font-bold mb-2">{l}</div>{vals(k).length ? <Line vals={vals(k)} /> : <div className="text-xs text-stone-400 py-6 text-center">Нет данных</div>}</Card>)}<Card cls="p-4 sm:col-span-2"><div className="flex justify-between items-center mb-3"><b className="text-sm">Дни с отметками</b><span className="text-xs text-stone-400">последние 14 дней</span></div><div className="flex gap-1.5">{days.map(d => <div key={d} title={fmtRus(d)} className="flex-1 h-8 rounded-md" style={{ background: st.diary[d] ? "var(--acc)" : "rgba(120,113,108,.12)" }} />)}</div></Card></div>}{diaryInsights().map((i, ix) => <div key={ix} className="rounded-xl bg-stone-100 dark:bg-white/5 p-3 text-sm mb-2">{i.t}</div>)}</div>; }

function ReportPage() { const st = useStore(); const daysCount = Object.keys(st.diary).length; const favs = Object.keys(st.fav).map(id => RECIPES.find(r => r.id === id)).filter(Boolean) as Recipe[];
  const avg = (k: string) => { const a = Object.values(st.diary).slice(-7).map((d: any) => d[k]).filter((v: any) => v != null) as number[]; return a.length ? (a.reduce((x, y) => x + y, 0) / a.length).toFixed(1) : "—"; };
  return <div className="p-4 max-w-2xl mx-auto"><h1 className="text-2xl font-bold mb-1">Недельный отчёт 📊</h1><p className="text-sm text-stone-500 mb-4">Итоги недели. Честно и без давления.</p>
    <div className="grid grid-cols-2 gap-3 mb-4"><Card cls="p-4 text-center"><div className="text-3xl font-bold" style={{ color: "var(--acc)" }}>{daysCount}</div><div className="text-xs text-stone-500">дней дневника</div></Card><Card cls="p-4 text-center"><div className="text-3xl font-bold" style={{ color: "var(--acc)" }}>{Object.keys(st.cooked).length}</div><div className="text-xs text-stone-500">блюд приготовлено</div></Card></div>
    <Card cls="p-4 mb-4"><h3 className="font-bold text-sm mb-3">Средние значения (1–5)</h3>{[["Энергия", avg("energy")], ["Сон", avg("sleep")], ["Тяга к сладкому", avg("craving")]].map(([l, v]) => <div key={l} className="flex justify-between py-1.5 text-sm border-b border-stone-100 dark:border-white/5 last:border-0"><span>{l}</span><b style={{ color: "var(--acc)" }}>{v}</b></div>)}</Card>
    {favs.length > 0 && <Card cls="p-4 mb-4"><h3 className="font-bold text-sm mb-2">Понравившиеся блюда ❤️</h3>{favs.slice(0, 4).map(r => <div key={r.id} className="text-sm py-1">{r.emoji} {r.title}</div>)}</Card>}
    <Card cls="p-4 mb-4"><h3 className="font-bold text-sm mb-2">Что было самым сложным?</h3><div className="flex flex-wrap gap-1.5">{["Готовка", "Питание вне дома", "Тяга к сладкому", "Планирование", "Ничего особенного"].map(x => <Chip key={x} on={st.weekReview?.hard === x} onClick={() => setSt(s => { s.weekReview = { ...s.weekReview, hard: x }; })}>{x}</Chip>)}</div></Card>
    <Card cls="p-4 mb-4"><h3 className="font-bold text-sm mb-2">Одна небольшая цель на неделю</h3>{["Заполнять дневник 5 дней", "Приготовить 2 новых блюда", "Сделать заготовки в воскресенье", "Овощи в каждый приём пищи", "Ложиться до 23:00"].map(x => <div key={x}><Toggle on={st.weekReview?.goal === x} set={(v: boolean) => setSt(s => { s.weekReview = { ...s.weekReview, goal: v ? x : null }; })} label={x} /></div>)}</Card>
    <div className="grid grid-cols-2 gap-2"><Btn onClick={() => go("#/nutritionist")}>📤 Нутрициологу</Btn><Btn variant="soft" onClick={() => window.print()}>🖨 PDF</Btn></div>
    <div className="text-[10px] text-stone-400 mt-3">Отчёт уходит специалисту только с вашего согласия.</div></div>; }

function ModePage({ mode }: any) { const info = MODE_INFO[mode]; const recipes = RECIPES.filter(r => r.mode === mode);
  return <div className="p-4 max-w-3xl mx-auto"><div className="rounded-3xl p-6 mb-4 text-white" style={{ background: "linear-gradient(135deg,var(--acc),var(--acc2))" }}><div className="text-4xl mb-2">{info.emoji}</div><h1 className="text-2xl font-bold mb-2">{info.title}</h1><p className="text-sm opacity-90">{info.desc}</p>{MODE() !== mode && <button onClick={() => { setSt(s => { s.profile.mode = mode; }); emit(); }} className="mt-3 text-xs bg-white/20 px-3 py-2 rounded-xl font-semibold">Переключить режим</button>}</div>
    <Card cls="p-4 mb-4"><h2 className="font-bold mb-2">Правила</h2>{info.rules.map((r: string, i: number) => <div key={i} className="flex gap-2 py-1 text-sm"><span style={{ color: "var(--acc)" }}>•</span>{r}</div>)}</Card>
    <div className="grid sm:grid-cols-2 gap-4 mb-4"><Card cls="p-4"><h3 className="font-bold text-sm mb-2">✅ Можно</h3>{info.allowed.map((x: string) => <div key={x} className="text-sm py-0.5">{x}</div>)}</Card><Card cls="p-4"><h3 className="font-bold text-sm mb-2">🟡 Ограничить</h3>{info.limit.map((x: string) => <div key={x} className="text-sm py-0.5 text-stone-500">{x}</div>)}</Card></div>
    <Card cls="p-4 mb-4"><h2 className="font-bold mb-2">Примерное меню на день</h2>{["breakfast", "lunch", "dinner"].map(cat => { const r = recipes.find(x => x.cat === cat)!; return <div key={cat} className="flex items-center gap-3 py-2 border-b border-stone-100 dark:border-white/5 last:border-0 cursor-pointer" onClick={() => go("#/recipe/" + r.id)}><span className="text-2xl">{r.emoji}</span><div><div className="text-sm font-semibold">{r.title}</div><div className="text-[11px] text-stone-400">{CATR[cat]} · {r.time} мин</div></div></div>; })}</Card>
    <div className="flex gap-2 mb-4"><Btn onClick={() => go("#/recipes")}>Смотреть {recipes.length} рецептов</Btn><Btn variant="soft" onClick={() => go("#/learn")}>Уроки</Btn></div></div>; }

function ChoosePage() {
  const rows = [["Основные продукты", "Мясо, рыба, яйца, жиры, зелень, низкоуглеводные овощи", "Преимущественно продукты животного происхождения"], ["Разнообразие блюд", "Высокое", "Более ограниченное"], ["Количество ингредиентов", "Среднее", "Небольшое"], ["Семейное питание", "Легко адаптируется", "Требует отдельной адаптации гарниров"], ["Время приготовления", "От 10 минут до сложных блюд", "Часто минимальное"], ["Считать углеводы", "Да", "Обычно меньше"], ["Питание в кафе", "Относительно легко подобрать", "Выбор более ограничен"], ["Новичку", "Возможен мягкий переход", "Лучше после оценки переносимости"], ["Занятому человеку", "Да, при наличии заготовок", "Да, простые блюда"], ["Готовить на несколько дней", "Да", "Да"]];
  return <div className="p-4 max-w-3xl mx-auto"><h1 className="text-2xl font-bold mb-1">Какой формат подойдёт мне? 🧭</h1><p className="text-sm text-stone-500 mb-4">Не уговорить, а помочь понять различия и выбрать реалистичный вариант.</p>
    <div className="grid sm:grid-cols-2 gap-4 mb-4">
      <Card cls="p-5"><div className="text-3xl mb-2">🥑</div><h2 className="font-bold mb-2">Кето</h2><p className="text-sm text-stone-600 dark:text-stone-300 mb-3">{MODE_INFO.keto.desc}</p><div className="text-xs font-bold uppercase text-stone-400 mb-1">Бытовые плюсы</div><ul className="text-sm space-y-1 mb-3">{["Рацион разнообразный", "Можно готовить для всей семьи", "Легко адаптировать домашние рецепты", "Есть овощи, супы и десерты", "Удобно брать с собой"].map(x => <li key={x}>＋ {x}</li>)}</ul><div className="text-xs font-bold uppercase text-stone-400 mb-1">Возможные сложности</div><ul className="text-sm space-y-1 text-stone-500">{["Нужно следить за углеводами", "Внимательно читать составы", "Непривычно планировать гарниры", "Не всем подходит много жирного", "При заболеваниях — к врачу"].map(x => <li key={x}>− {x}</li>)}</ul></Card>
      <Card cls="p-5"><div className="text-3xl mb-2">🥩</div><h2 className="font-bold mb-2">Карнивор</h2><p className="text-sm text-stone-600 dark:text-stone-300 mb-3">{MODE_INFO.carnivore.desc}</p><div className="text-xs font-bold uppercase text-stone-400 mb-1">Бытовые плюсы</div><ul className="text-sm space-y-1 mb-3">{["Простой список продуктов", "Минимум ингредиентов", "Подходит нелюбящим сложные рецепты", "Удобные заготовки", "Быстрая готовка"].map(x => <li key={x}>＋ {x}</li>)}</ul><div className="text-xs font-bold uppercase text-stone-400 mb-1">Возможные сложности</div><ul className="text-sm space-y-1 text-stone-500">{["Более однообразный рацион", "Сложнее есть вместе с семьёй", "Не всем подходит без растительной пищи", "Важно следить за пищеварением", "Подходит не каждому, при заболеваниях — к врачу"].map(x => <li key={x}>− {x}</li>)}</ul></Card>
    </div>
    <Card cls="p-4 mb-4 overflow-x-auto"><h2 className="font-bold mb-3">Сравнение</h2><table className="w-full text-xs min-w-[520px]"><thead><tr className="text-left"><th className="py-2 pr-2">Критерий</th><th className="py-2 pr-2">🥑 Кето</th><th className="py-2">🥩 Карнивор</th></tr></thead><tbody>{rows.map(([a, b, c0]) => <tr key={a} className="border-t border-stone-100 dark:border-white/5"><td className="py-2 pr-2 font-semibold">{a}</td><td className="py-2 pr-2">{b}</td><td className="py-2">{c0}</td></tr>)}</tbody></table></Card>
    <div className="rounded-2xl p-4 text-sm mb-5" style={{ background: "var(--accbg)" }}>Не существует одного рациона, который подходит абсолютно всем. Выбор зависит от состояния здоровья, самочувствия, пищевых предпочтений, образа жизни и рекомендаций врача при наличии заболеваний.</div>
    <Btn cls="w-full" onClick={() => go("#/quiz")}>Пройти тест «Какой план подходит именно вам?» →</Btn></div>; }

const QUIZ: [string, string[]][] = [["Сколько времени готовы тратить на готовку?", ["До 15 минут", "До 30 минут", "Сколько нужно"]], ["Готовите отдельно для себя или для всей семьи?", ["Для себя", "Для всей семьи", "По-разному"]], ["Любите овощи и зелень?", ["Да, очень", "Не очень", "Равнодушно"]], ["Нужен максимально простой рацион?", ["Да", "Нет", "По настроению"]], ["Занимаетесь спортом?", ["Да", "Нет"]], ["Сколько тренировок в неделю?", ["0", "1–2", "3+"]], ["Какой тип тренировок?", ["Силовые", "Кардио", "Смешанные", "Не тренируюсь"]], ["Нужна ли еда с собой на работу?", ["Да", "Нет"]], ["Как часто питаетесь вне дома?", ["Редко", "1–2 раза в неделю", "Часто"]], ["Готовить один-два раза в неделю — это про вас?", ["Да, идеально", "Нет, люблю готовить чаще"]], ["Есть ли продукты, которые не едите?", ["Нет", "Да"]], ["Бюджет на питание?", ["Эконом", "Средний", "Гибкий"]], ["Есть заболевания или регулярный приём лекарств?", ["Нет", "Да"]], ["Основная цель?", ["Удобство", "Контроль аппетита", "Снижение веса", "Спортивный режим", "Меньше сладкого", "Знакомство с новым рационом"]]];
function QuizPage() { const st = useStore(); const [i, setI] = useState(0); const ans: string[] = st.quiz?.ans || [];
  const pick = (a: string) => { const na = [...ans]; na[i] = a; setSt(s => { s.quiz = { ans: na }; }); setI(i + 1); };
  if (i >= QUIZ.length) { const simple = ans[0] === "До 15 минут" || ans[3] === "Да" || ans[9] === "Да, идеально"; const fam = ans[1] === "Для всей семьи"; const sport = ans[4] === "Да" && ans[5] !== "0"; const veg = ans[2] === "Да, очень"; const med = ans[12] === "Да";
    let rec2: string, prog: any;
    if (simple && !veg) { rec2 = "Вам важны простые блюда и минимум готовки. Посмотрите программу «Карнивор: знакомство с рационом». Формат более ограничителен — начните с малого и наблюдайте за самочувствием."; prog = PROGRAMS.find(p => p.id === "p4"); }
    else if (fam) { rec2 = "Вы готовите для всей семьи, поэтому вам может подойти семейный кето-конструктор: одна основа — разные гарниры."; prog = PROGRAMS.find(p => p.id === "p7"); }
    else if (sport) { rec2 = "Вы активно тренируетесь. Для вас создан спортивный вариант меню с настройкой порций и ориентировочного белка. Рост результатов не обещаем — только удобство."; prog = PROGRAMS.find(p => p.id === "p8"); }
    else if (simple) { rec2 = "С учётом ваших ответов вам может быть удобнее начать с мягкого кето-формата без сложной готовки."; prog = PROGRAMS.find(p => p.id === "p3"); }
    else { rec2 = "Вы пока не уверены. Начните с ознакомительной программы и понаблюдайте за самочувствием."; prog = PROGRAMS.find(p => p.id === "p9"); }
    if (med) rec2 += " При заболеваниях и приёме лекарств изменения рациона стоит обсудить с врачом до старта.";
    return <div className="p-4 max-w-xl mx-auto text-center"><div className="text-5xl mb-4">{prog.emoji}</div><h1 className="text-2xl font-bold mb-3">Результат</h1><Card cls="p-5 mb-4 text-left"><p className="text-sm mb-3">{rec2}</p><div className="rounded-xl p-3" style={{ background: "var(--accbg)" }}><b className="text-sm">{prog.title}</b><div className="text-xs text-stone-500 mt-1">{prog.desc}</div></div></Card><div className="grid grid-cols-2 gap-2"><Btn onClick={() => go("#/programs")}>Смотреть программы</Btn><Btn variant="soft" onClick={() => { setI(0); setSt(s => { s.quiz = null; }); }}>Заново</Btn></div></div>; }
  return <div className="p-4 max-w-xl mx-auto"><div className="flex justify-between text-xs text-stone-400 mb-2"><span>Вопрос {i + 1} из {QUIZ.length}</span>{i > 0 && <button className="underline" onClick={() => setI(i - 1)}>← назад</button>}</div><div className="h-1.5 rounded-full bg-stone-200 dark:bg-white/10 mb-5"><div className="h-full rounded-full" style={{ width: i / QUIZ.length * 100 + "%", background: "var(--acc)" }} /></div><Card cls="p-5"><h2 className="text-lg font-bold mb-4">{QUIZ[i][0]}</h2>{QUIZ[i][1].map(a0 => <button key={a0} onClick={() => pick(a0)} className="w-full text-left px-4 py-3 rounded-xl border border-stone-200 dark:border-white/15 mb-2 text-sm font-medium">{a0}</button>)}</Card></div>; }

function ProgramsPage() { const [flt, setFlt] = useState("all"); const list = PROGRAMS.filter(p => flt === "all" || p.mode === flt || p.mode === "both");
  return <div className="p-4 max-w-3xl mx-auto"><h1 className="text-2xl font-bold mb-1">Программы 🎯</h1><p className="text-sm text-stone-500 mb-4">Под занятых, семьи, спортсменов и тех, кто присматривается.</p><div className="flex gap-2 mb-4">{[["all", "Все"], ["keto", "🥑 Кето"], ["carnivore", "🥩 Карнивор"]].map(([v, l]) => <Chip key={v} on={flt === v} onClick={() => setFlt(v)}>{l}</Chip>)}</div>
    <div className="grid sm:grid-cols-2 gap-3">{list.map(p => <Card key={p.id} cls="p-4 flex flex-col"><div className="flex items-center gap-2 mb-1"><span className="text-2xl">{p.emoji}</span><b className="text-sm flex-1">{p.title}</b></div><p className="text-xs text-stone-500 mb-2">{p.desc}</p><ul className="text-xs space-y-1 mb-3 flex-1">{p.pts.map(x => <li key={x}>✓ {x}</li>)}</ul><div className="flex items-center justify-between"><span className={`text-[10px] px-2 py-0.5 rounded-full font-bold ${p.price === "free" ? "bg-emerald-100 text-emerald-700 dark:bg-emerald-900/40 dark:text-emerald-300" : ""}`} style={p.price !== "free" ? { background: "var(--accbg)", color: "var(--acc)" } : {}}>{p.price === "free" ? "бесплатно" : "premium"}</span><Btn cls="!py-1.5 !px-3 !text-xs" onClick={() => { setSt(s => { s.menu = genMenu(p.mode === "carnivore" ? "carnivore" : "keto", 7, P().meals || 3); }); checkAch(); emit(); go("#/menu"); }}>Применить</Btn></div></Card>)}</div></div>; }

function BudgetPage() { const [people, setPeople] = useState(2); const [days, setDays] = useState(7); const [budget, setBudget] = useState(5000);
  const basket = (type: string) => { const base: any = { "Обычная семейная корзина": { d: 420, p: 1 }, "Кето-корзина": { d: 460, p: 1.05 }, "Бюджетная кето-версия": { d: 360, p: 1 }, "Карнивор-корзина": { d: 520, p: 1.1 }, "Разнообразная версия": { d: 540, p: 1.15 } }[type]; return Math.round(base.d * people * days * base.p); };
  return <div className="p-4 max-w-3xl mx-auto"><h1 className="text-2xl font-bold mb-1">Питаемся без лишних расходов 💰</h1><p className="text-sm text-stone-500 mb-4">Кето и карнивор — не обязательно стейки и авокадо. Основа — обычные продукты.</p>
    <Card cls="p-4 mb-4"><h3 className="font-bold text-sm mb-2">Принципы бюджетного меню</h3>{["Обычные продукты вместо «специальных» кето-товаров", "Яйца, курица, фарш, недорогая рыба, субпродукты — база", "Готовить большими порциями и замораживать", "Планировать меню до магазина", "Один продукт — несколько блюд", "Адаптировать семейные блюда, а не готовить отдельное меню"].map(x => <div key={x} className="text-sm py-1 flex gap-2"><span style={{ color: "var(--acc)" }}>•</span>{x}</div>)}</Card>
    <Card cls="p-4 mb-4"><h3 className="font-bold mb-3">Калькулятор бюджета</h3><div className="grid grid-cols-3 gap-3 mb-3"><Field label="Членов семьи"><Input type="number" value={people} onChange={(e: any) => setPeople(+e.target.value || 1)} /></Field><Field label="Дней"><Input type="number" value={days} onChange={(e: any) => setDays(+e.target.value || 1)} /></Field><Field label="Бюджет, ₽/нед"><Input type="number" value={budget} onChange={(e: any) => setBudget(+e.target.value || 0)} /></Field></div>
      {["Обычная семейная корзина", "Кето-корзина", "Бюджетная кето-версия", "Карнивор-корзина", "Разнообразная версия"].map(t => { const v = basket(t); return <div key={t} className="py-2 border-b border-stone-100 dark:border-white/5 last:border-0"><div className="flex justify-between text-sm"><span>{t}</span><b style={{ color: v > budget ? "#dc2626" : "var(--acc)" }}>≈ {v.toLocaleString("ru-RU")} ₽</b></div><div className="text-[11px] text-stone-400">{Math.round(v / days)} ₽/день · {Math.round(v / (days * people * 3))} ₽/порция {v > budget && "· выше бюджета"}</div></div>; })}
      <div className="text-[11px] text-stone-400 mt-3">Приложение помогает составить меню так, чтобы расходы были сопоставимы с привычным домашним питанием. Итоговая стоимость зависит от региона, цен, продуктов и состава семьи.</div></Card>
    <div className="rounded-2xl p-4 text-sm mb-4" style={{ background: "var(--accbg)" }}><b>Главный принцип:</b> не нужно покупать отдельный набор продуктов. Мясо, птица, рыба, яйца и сыры — общие для всей семьи. Отличаются только гарниры.</div>
    <Btn variant="soft" onClick={() => go("#/recipes")}>Открыть фильтр «бюджетно» →</Btn></div>; }

function LearnPage() { const st = useStore(); const [open, setOpen] = useState<number | null>(null); const done = Object.keys(st.lessons).length;
  return <div className="p-4 max-w-2xl mx-auto"><h1 className="text-2xl font-bold mb-1">Начало пути 🎓</h1><p className="text-sm text-stone-500 mb-3">15 коротких уроков простым языком. Пройдено {done} из {LESSONS.length}.</p><div className="h-2 rounded-full bg-stone-200 dark:bg-white/10 mb-5"><div className="h-full rounded-full" style={{ width: done / LESSONS.length * 100 + "%", background: "var(--acc)" }} /></div>
    {LESSONS.map(l => <Card key={l.id} cls="mb-2 overflow-hidden"><button onClick={() => setOpen(open === l.id ? null : l.id)} className="w-full flex items-center gap-3 p-4 text-left"><span className="w-8 h-8 rounded-full flex items-center justify-center text-xs font-bold flex-shrink-0 text-white" style={{ background: st.lessons[l.id] ? "var(--acc)" : "rgba(120,113,108,.25)" }}>{st.lessons[l.id] ? "✓" : l.id}</span><span className="flex-1"><b className="text-sm">{l.t}</b><div className="text-[11px] text-stone-400">{l.m} мин чтения</div></span><span>{open === l.id ? "▲" : "▼"}</span></button>
      {open === l.id && <div className="px-4 pb-4">{l.txt.map((p, i) => <p key={i} className="text-sm mb-3">{p}</p>)}<div className="rounded-xl p-3 mb-3" style={{ background: "var(--accbg)" }}><b className="text-sm block mb-2">Проверьте себя: {l.q.q}</b>{l.q.a.map((a0, i) => <button key={i} onClick={() => { if (i === l.q.ok) { setSt(s => { s.lessons[l.id] = true; }); checkAch(); emit(); } else alert("Не совсем — перечитайте урок выше 🙂"); }} className="block w-full text-left px-3 py-2 rounded-lg bg-white/70 dark:bg-black/20 text-sm mb-1.5">{a0}</button>)}</div>{st.lessons[l.id] && <div className="text-xs font-bold" style={{ color: "var(--acc)" }}>✅ Урок пройден</div>}</div>}</Card>)}</div>; }

function CafePage() { const [cat, setCat] = useState("restaurant"); const c = CAFE[cat];
  return <div className="p-4 max-w-2xl mx-auto"><h1 className="text-2xl font-bold mb-1">Что выбрать в кафе 🍽️</h1><p className="text-sm text-stone-500 mb-4">Как адаптировать блюдо под ваш режим ({MODE_INFO[MODE()].title.toLowerCase()}).</p>
    <div className="grid grid-cols-4 gap-2 mb-4">{Object.entries(CAFE).map(([k, v]: any) => <button key={k} onClick={() => setCat(k)} className={`p-2.5 rounded-xl border text-center ${cat === k ? "border-2" : "border-stone-200 dark:border-white/10"}`} style={cat === k ? { borderColor: "var(--acc)", background: "var(--accbg)" } : {}}><div className="text-xl">{v.e}</div><div className="text-[10px] font-semibold mt-1">{v.t}</div></button>)}</div>
    <Card cls="p-5"><h2 className="font-bold mb-3">{c.e} {c.t}</h2>{c.tips.map((t: string) => <div key={t} className="flex gap-2 py-1.5 text-sm border-b border-stone-100 dark:border-white/5 last:border-0"><span style={{ color: "var(--acc)" }}>•</span>{t}</div>)}<div className="mt-4 rounded-xl p-3 text-xs" style={{ background: "var(--accbg)" }}>{MODE() === "carnivore" ? "В карнивор выбор уже: ищите чистое мясо, рыбу, яйца без соусов и гарниров." : "В кето почти любое блюдо адаптируется: гарнир → салат или овощи, соус отдельно."}</div></Card></div>; }

function NavigatorPage() { const [q, setQ] = useState(""); const [res, setRes] = useState<any>(null); const [file, setFile] = useState<any>(null);
  const scan = () => { if (!file) return; setRes({ loading: true }); setTimeout(() => setRes({ loading: false, name: "Результат по этикетке", carbs: 6.4, sugar: 4.2, starch: true, syrup: false, port: "30 г", notes: ["Углеводы указаны на 100 г — пересчитайте на порцию", "Добавленный сахар на 2-м месте состава", "Есть крахмал как загуститель"] }), 1400); };
  const search = () => { const t = q.toLowerCase(); let v: any = { name: q };
    if (/йогурт|творож/.test(t)) v = { ...v, carbs: 6.8, sugar: 5.9, starch: true, port: "125 г", notes: ["Пересчитайте на свою порцию", "Часто есть сахар и крахмал", "Ищите варианты без добавок"] };
    else if (/кетчуп|соус/.test(t)) v = { ...v, carbs: 24, sugar: 21, starch: true, syrup: true, port: "15 г", notes: ["Сахар и сироп в составе", "~3 г углеводов на столовую ложку", "Легко перебрать незаметно"] };
    else if (/молоко/.test(t)) v = { ...v, carbs: 4.7, sugar: 4.7, port: "250 мл", notes: ["Лактоза — молочный сахар, ~12 г на стакан"] };
    else if (/хлеб|батон|мюсли|каша/.test(t)) v = { ...v, carbs: 45, sugar: 3, starch: true, port: "100 г", notes: ["Высокие углеводы", "Мюсли часто содержат сиропы даже с пометкой «фитнес»"] };
    else if (/колбас|сосис/.test(t)) v = { ...v, carbs: 2.5, sugar: 0.8, starch: true, port: "100 г", notes: ["Часто крахмал, сахар и декстроза", "Читайте состав конкретного производителя"] };
    else v = { ...v, carbs: null, notes: ["Не нашли в базе. Проверьте этикетку: углеводы на порцию, сахар/сироп/крахмал в составе."] };
    setRes(v); };
  return <div className="p-4 max-w-2xl mx-auto"><h1 className="text-2xl font-bold mb-1">Кето-навигатор в магазине 🛍️</h1><p className="text-sm text-stone-500 mb-4">Введите продукт или загрузите фото состава. Не делим продукты на «хорошие» и «плохие».</p>
    <div className="flex gap-2 mb-4"><Input placeholder="Например: йогурт, кетчуп, молоко…" value={q} onChange={(e: any) => setQ(e.target.value)} onKeyDown={(e: any) => e.key === "Enter" && search()} /><Btn onClick={search}>Проверить</Btn></div>
    <Card cls="p-4 mb-4"><div className="text-sm font-semibold mb-2">📷 Или фото этикетки</div><input type="file" accept="image/*" onChange={(e: any) => setFile(e.target.files?.[0])} className="text-xs mb-2 w-full" /><Btn variant="soft" onClick={scan} disabled={!file}>Распознать состав</Btn></Card>
    {res?.loading && <Card cls="p-6 text-center text-stone-400"><div className="animate-pulse text-3xl mb-2">🔍</div>Анализируем состав…</Card>}
    {res && !res.loading && <Card cls="p-4"><h3 className="font-bold mb-3">{res.name || "Результат"}</h3>{res.carbs != null && <div className="grid grid-cols-3 gap-2 mb-3">{[["Углеводы", res.carbs + " г/100г", res.carbs > 10], ["Сахар", res.sugar + " г", res.sugar > 5], ["Порция", res.port, false]].map(([l, v, warn]: any) => <div key={l} className={`rounded-xl p-3 text-center ${warn ? "bg-amber-50 dark:bg-amber-900/20" : "bg-stone-50 dark:bg-white/5"}`}><div className="text-xs text-stone-400">{l}</div><div className="font-bold text-sm" style={warn ? { color: "#d97706" } : {}}>{v}</div>{warn && <div className="text-[10px] text-amber-600 mt-0.5">многовато</div>}</div>)}</div>}{res.starch && <div className="text-xs">⚠️ В составе есть крахмал</div>}{res.syrup && <div className="text-xs">⚠️ В составе есть сироп</div>}{(res.notes || []).map((n: string) => <div key={n} className="text-xs py-0.5">• {n}</div>)}<div className="text-[11px] text-stone-400 mt-2">Это информация для выбора, а не запрет. Размер порции решает.</div></Card>}</div>; }

function PrepPage() { const items = [["Запечённое мясо", "40 мин", "3–4 дня"], ["Курица целиком", "60 мин", "3 дня"], ["Яйца вкрутую", "12 мин", "7 дней"], ["Котлеты", "35 мин", "3 дня / месяц в морозилке"], ["Рыба запечённая", "25 мин", "1–2 дня"], ["Бульон", "2–4 часа", "4 дня / 3 мес."], ["Нарезанные овощи", "15 мин", "2–3 дня"], ["Домашний соус", "10 мин", "5 дней"]];
  const plan = [["0–10 мин", "Разогрейте духовку до 190°C, поставьте вариться яйца и бульон."], ["10–20 мин", "Подготовьте мясо и курицу: специи, на противень."], ["20–55 мин", "Пока духовка работает — нарежьте овощи, сделайте соус, сформируйте котлеты."], ["55–75 мин", "Запекаем вторую партию, разбираем первую по контейнерам."], ["75–90 мин", "Подпишите контейнеры с датой, уберите в холодильник и морозилку."]];
  return <div className="p-4 max-w-2xl mx-auto"><h1 className="text-2xl font-bold mb-1">Заготовки на неделю 📦</h1><p className="text-sm text-stone-500 mb-4">60–90 минут раз в неделю — и еда собирается как конструктор.</p>
    <Card cls="p-4 mb-4 overflow-x-auto"><h3 className="font-bold text-sm mb-2">Что заготовить</h3><table className="w-full text-sm min-w-[420px]"><tbody>{items.map(([n, t, s0]) => <tr key={n} className="border-b border-stone-100 dark:border-white/5 last:border-0"><td className="py-2">{n}</td><td className="py-2 text-stone-400 text-xs">{t}</td><td className="py-2 text-xs text-right" style={{ color: "var(--acc)" }}>хранится {s0}</td></tr>)}</tbody></table></Card>
    <Card cls="p-4 mb-4"><h3 className="font-bold text-sm mb-3">План на 90 минут</h3>{plan.map(([t, s0]) => <div key={t} className="flex gap-3 mb-3"><span className="w-16 flex-shrink-0 text-xs font-bold pt-0.5" style={{ color: "var(--acc)" }}>{t}</span><span className="text-sm">{s0}</span></div>)}</Card>
    <div className="rounded-xl p-3 text-xs mb-4" style={{ background: "var(--accbg)" }}>⚠️ Безопасность: остужайте быстро, храните в закрытых контейнерах, не держите готовую еду при комнатной температуре дольше 2 часов.</div>
    <Btn onClick={() => go("#/recipes")}>Найти рецепты для заготовок →</Btn></div>; }

function AntisryvPage() { const [step, setStep] = useState(0); const [cause, setCause] = useState(""); const [toast, setToast] = useState("");
  const steps = [<Card key="a0" cls="p-5 text-center"><div className="text-4xl mb-3">🫂</div><h2 className="text-xl font-bold mb-2">Тяга к сладкому или желание всё бросить — это нормально</h2><p className="text-sm text-stone-500 mb-4">Без стыда, «слабой воли» и наказаний. Спокойно разберёмся.</p><Btn onClick={() => setStep(1)}>Продолжить</Btn></Card>,
  <Card key="a1" cls="p-5"><h3 className="font-bold mb-3">Шаг 1. Когда вы ели в последний раз?</h3>{["Меньше 2 часов назад", "2–4 часа назад", "Больше 4 часов назад", "Не помню"].map(x => <button key={x} onClick={() => setStep(2)} className="w-full text-left px-4 py-3 rounded-xl border border-stone-200 dark:border-white/15 mb-2 text-sm">{x}</button>)}</Card>,
  <Card key="a2" cls="p-5"><h3 className="font-bold mb-3">Шаг 2. Что, возможно, за этим стоит?</h3><div className="flex flex-wrap gap-2 mb-4">{["Недосып", "Стресс", "Просто хочется", "Голод", "Скука", "Усталость"].map(x => <Chip key={x} on={cause === x} onClick={() => setCause(x)}>{x}</Chip>)}</div><p className="text-sm text-stone-500 mb-4">{cause === "Недосып" ? "Недосып усиливает тягу к быстрым углеводам — это физиология, а не слабость." : cause === "Стресс" ? "Еда часто снимает напряжение. Попробуйте также воду и короткую паузу." : cause === "Голод" ? "Если давно не ели — сначала сытный приём пищи. Тяга часто уходит сама." : "Иногда хочется просто потому, что хочется. Это нормально."}</p><Btn onClick={() => setStep(3)}>Дальше</Btn></Card>,
  <Card key="a3" cls="p-5"><h3 className="font-bold mb-3">Шаг 3. Простой сытный вариант прямо сейчас</h3>{[["🥚", "Яйца с сыром — 5 минут"], ["🥩", "Кусочек мяса или котлета из заготовок"], ["🧀", "(кето) горсть орехов или ломтик сыра"], ["🥒", "Овощная нарезка со сметанным соусом"]].map(([e, t]) => <div key={t} className="flex gap-3 items-center py-2 border-b border-stone-100 dark:border-white/5 text-sm"><span className="text-xl">{e}</span>{t}</div>)}<Btn cls="w-full mt-4" onClick={() => setStep(4)}>Дальше</Btn></Card>,
  <Card key="a4" cls="p-5 text-center"><div className="text-4xl mb-3">💚</div><h3 className="font-bold mb-2">Два хороших варианта</h3><p className="text-sm text-stone-500 mb-2">1. Выбрать сытный вариант выше и продолжить в своём ритме.</p><p className="text-sm text-stone-500 mb-4">2. Осознанно разрешить себе то, что хочется — без вины. Со следующего приёма пищи просто возвращаемся к рациону.</p><div className="grid grid-cols-2 gap-2"><Btn onClick={() => { setToast("Возвращаемся к привычному рациону со следующего приёма пищи 🌿"); setTimeout(() => go("#/home"), 1600); }}>Продолжаю 🌿</Btn><Btn variant="soft" onClick={() => go("#/nutritionist")}>Нутрициологу</Btn></div></Card>];
  return <div className="p-4 max-w-xl mx-auto"><button onClick={() => go("#/home")} className="text-sm text-stone-500 mb-3">← На главную</button>{steps[step]}{toast && <Toast msg={toast} onClose={() => setToast("")} />}</div>; }

function RemindersPage() { const st = useStore(); const rs = reminderState(); const levels = [["minimal", "Минимум", "Только дневник"], ["standard", "Стандарт", "Главное без лишнего"], ["active", "Активно", "Полное сопровождение"], ["custom", "Свои", "Полная настройка"]];
  return <div className="p-4 max-w-2xl mx-auto"><h1 className="text-2xl font-bold mb-1">Напоминания ⏰</h1><p className="text-sm text-stone-500 mb-4">Без лишних сообщений — выберите комфортный уровень.</p>
    <div className="grid grid-cols-2 gap-2 mb-5">{levels.map(([v, t, dd]) => <button key={v} onClick={() => setSt(s => { s.remSet.level = v; })} className={`p-3 rounded-xl border text-left ${st.remSet.level === v ? "border-2" : "border-stone-200 dark:border-white/10"}`} style={st.remSet.level === v ? { borderColor: "var(--acc)", background: "var(--accbg)" } : {}}><b className="text-sm block">{t}</b><span className="text-[11px] text-stone-500">{dd}</span></button>)}</div>
    {rs.map((r: any) => <Card key={r.id} cls="p-3 mb-2 flex items-center gap-3"><span className="text-xl">{r.ic}</span><span className="flex-1 text-sm font-medium">{r.t}</span>{st.remSet.level === "custom" && <input type="time" defaultValue="20:00" className="text-xs bg-transparent border border-stone-200 dark:border-white/15 rounded-lg px-2 py-1" />}<Toggle on={r.on} set={(v: boolean) => { if (st.remSet.level !== "custom") { setSt(s => { s.remSet.level = "custom"; REMS.forEach(x => { s.remSet.custom[x.id] = x.def; }); s.remSet.custom[r.id] = v; }); } else setSt(s => { s.remSet.custom[r.id] = v; }); }} label="" /></Card>)}
    <div className="text-[11px] text-stone-400 mt-3">Демо: push подключается отдельно (Firebase / OneSignal / Telegram-бот).</div></div>; }

function NutritionistPage() { const st = useStore(); const [msg, setMsg] = useState(""); const [files, setFiles] = useState<any[]>([]); const [modal, setModal] = useState(""); const [form, setForm] = useState({ date: "", time: "", type: "video" }); const [ok, setOk] = useState(false);
  const send = () => { if (!msg.trim()) return; setSt(s => { s.msgs.push({ id: uid(), from: "me", text: msg, date: Date.now() }); }); setMsg(""); setTimeout(() => { setSt(s => { s.msgs.push({ id: uid(), from: "doc", text: "Здравствуйте! Спасибо за сообщение — отвечу в течение рабочего дня 🙂.", date: Date.now() }); }); }, 900); };
  return <div className="p-4 max-w-2xl mx-auto"><h1 className="text-2xl font-bold mb-4">Мой нутрициолог 💬</h1>
    <Card cls="p-5 mb-4"><div className="flex gap-4 items-start"><div className="w-20 h-20 rounded-2xl flex items-center justify-center text-4xl flex-shrink-0" style={{ background: "linear-gradient(135deg,var(--accbg),var(--acc2))" }}>👩‍⚕️</div><div><h2 className="font-bold">{NUTRI.name}</h2><div className="text-xs text-stone-400 mb-2">{NUTRI.exp}</div><p className="text-sm text-stone-600 dark:text-stone-300">{NUTRI.about}</p></div></div>
      <div className="grid sm:grid-cols-2 gap-3 mt-4 text-xs"><div><div className="font-bold text-stone-400 uppercase mb-1">Образование</div>{NUTRI.edu.map(x => <div key={x} className="py-0.5">🎓 {x}</div>)}</div><div><div className="font-bold text-stone-400 uppercase mb-1">Сертификаты</div>{NUTRI.certs.map(x => <div key={x} className="py-0.5">📜 {x}</div>)}</div></div></Card>
    <div className="grid grid-cols-2 gap-2 mb-4"><Btn onClick={() => setModal("msg")}>✉️ Написать</Btn><Btn variant="soft" onClick={() => { setSt(s => { s.msgs.push({ id: uid(), from: "me", text: "📤 Отправляю дневник питания и недельный отчёт на проверку.", date: Date.now() }); }); setOk(true); }}>📤 Отправить дневник</Btn><Btn variant="soft" onClick={() => setModal("consult")}>📅 Консультация</Btn><Btn variant="soft" onClick={() => go("#/premium")}>🧭 Персональный разбор</Btn></div>
    <Card cls="p-4 mb-4"><h3 className="font-bold text-sm mb-2">Загрузить анализы / документы</h3><p className="text-xs text-stone-500 mb-2">Видит только специалист. Автоматически анализы не интерпретируются.</p><input type="file" multiple onChange={(e: any) => setFiles([...files, ...Array.from(e.target.files || [])])} className="text-xs w-full mb-2" />{files.map((f: any) => <div key={f.name} className="text-xs py-1">📎 {f.name}</div>)}{files.length > 0 && <Btn cls="!py-1.5 !text-xs mt-1" onClick={() => { setSt(s => { s.msgs.push({ id: uid(), from: "me", text: "📎 Документы: " + files.map(f => f.name).join(", "), date: Date.now() }); }); setFiles([]); setOk(true); }}>Отправить</Btn>}</Card>
    <Card cls="p-4 mb-4"><h3 className="font-bold text-sm mb-3">Переписка</h3>{st.msgs.length === 0 ? <div className="text-xs text-stone-400 py-3">Пока нет сообщений.</div> : <div className="space-y-2 mb-3 max-h-60 overflow-y-auto">{st.msgs.map((m0: any) => <div key={m0.id} className={`max-w-[85%] rounded-2xl px-3.5 py-2 text-sm ${m0.from === "me" ? "ml-auto text-white" : "bg-stone-100 dark:bg-white/10"}`} style={m0.from === "me" ? { background: "var(--acc)" } : {}}>{m0.text}</div>)}</div>}<div className="flex gap-2"><Input placeholder="Ваш вопрос…" value={msg} onChange={(e: any) => setMsg(e.target.value)} onKeyDown={(e: any) => e.key === "Enter" && send()} /><Btn onClick={send}>→</Btn></div></Card>
    <Card cls="p-4 mb-4"><h3 className="font-bold text-sm mb-3">Отзывы</h3>{NUTRI.reviews.map(([a, t]) => <div key={a} className="mb-3"><div className="text-xs font-bold" style={{ color: "var(--acc)" }}>{a} · ⭐⭐⭐⭐⭐</div><div className="text-sm text-stone-600 dark:text-stone-300">{t}</div></div>)}</Card>
    <div className="text-xs text-stone-400 mb-6">Специалист не ставит диагнозы и не отменяет лекарства.</div>
    <Modal open={modal === "consult"} onClose={() => setModal("")} title="Запись на консультацию"><Field label="Дата"><Input type="date" value={form.date} onChange={(e: any) => setForm({ ...form, date: e.target.value })} /></Field><Field label="Время"><Seg opts={[{ v: "10:00", l: "10:00" }, { v: "14:00", l: "14:00" }, { v: "18:00", l: "18:00" }]} val={form.time} set={(v: any) => setForm({ ...form, time: v })} /></Field><Field label="Формат"><Seg opts={[{ v: "video", l: "Видео" }, { v: "chat", l: "Чат" }]} val={form.type} set={(v: any) => setForm({ ...form, type: v })} /></Field><Btn cls="w-full" onClick={() => { if (!form.date || !form.time) { alert("Выберите дату и время"); return; } setSt(s => { s.consult = form; }); setModal(""); setOk(true); }}>Записаться</Btn></Modal>
    <Modal open={modal === "msg"} onClose={() => setModal("")} title="Сообщение"><textarea rows={4} value={msg} onChange={(e: any) => setMsg(e.target.value)} className="w-full px-3.5 py-2.5 rounded-xl border border-stone-200 dark:border-white/15 bg-white dark:bg-white/5 text-sm mb-3 outline-none" /><Btn cls="w-full" onClick={() => { send(); setModal(""); }}>Отправить</Btn></Modal>
    {ok && <Toast msg="Отправлено! Мария ответит в течение рабочего дня 💬" onClose={() => setOk(false)} />}</div>; }

function PremiumPage() { const st = useStore(); const [toast, setToast] = useState("");
  const tiers: any[] = [["free", "Бесплатный доступ", "0 ₽", "", ["Ограниченная библиотека рецептов", "Базовые правила питания", "Дневник самочувствия", "Одно примерное меню", "Простой список покупок"]], ["m", "Premium · месяц", "390 ₽", "/ мес", ["Все 37 рецептов + новинки каждый месяц", "Персональное меню 1/3/7 дней", "Конструктор блюд и «Мой холодильник»", "Автосписок покупок и бюджет", "Расширенная аналитика и отчёты", "Курс и программы", "«Что выбрать в кафе»"]], ["y", "Premium · год", "2 990 ₽", "/ год · −36%", ["Всё из месячной подписки", "Выгоднее на 42%", "Приоритетная поддержка"]], ["care", "Личное сопровождение", "4 900 ₽", "/ мес", ["Разбор анкеты", "Корректировка меню", "Обратная связь нутрициолога", "Анализ дневника питания", "Видеоконсультация", "Чат-сопровождение"]]];
  const buy = () => setToast("Покупки временно недоступны. Оформление новых тарифов приостановлено.");
  return <div className="p-4 max-w-3xl mx-auto"><div className="text-center mb-4"><h1 className="text-2xl font-bold mb-2">Не очередной список рецептов, а готовая система питания под вашу жизнь</h1><p className="text-sm text-stone-500 max-w-xl mx-auto">Меньше времени на планирование, понятные рецепты, готовые списки, наблюдение за самочувствием и поддержка.</p></div>
    <div className="p-3 mb-6 rounded-xl bg-amber-500/10 border border-amber-500/30 text-amber-700 dark:text-amber-300 text-xs text-center font-medium">⚠️ Оформление новых тарифов временно приостановлено. Все ранее предоставленные доступы остаются активными.</div>
    <div className="grid sm:grid-cols-2 gap-3 mb-6">{tiers.map(([id, t, price, per, pts]: any) => <Card key={id} cls="p-5 relative">{(id === "m" || id === "y") && <span className="absolute -top-2 right-4 text-[10px] px-2 py-0.5 rounded-full text-white font-bold" style={{ background: "var(--acc)" }}>популярно</span>}<b>{t}</b><div className="text-2xl font-bold my-2">{price}<span className="text-xs text-stone-400"> {per}</span></div>{pts.map((x: string) => <div key={x} className="text-xs py-1 flex gap-1.5"><span style={{ color: "var(--acc)" }}>✓</span>{x}</div>)}<Btn cls="w-full mt-3" variant={st.premium && id !== "free" ? "soft" : !st.premium && id === "free" ? "soft" : "primary"} onClick={id === "free" ? () => setToast("Базовый тариф включён по умолчанию.") : st.premium ? () => setToast("Premium уже активен ✨") : buy}>{st.premium && id !== "free" && id !== "care" ? "Активен" : !st.premium && id === "free" ? "Активен" : id === "free" ? "Базовый" : "Недоступно"}</Btn></Card>)}</div>
    <Card cls="p-5 mb-6"><h3 className="font-bold mb-3">Самостоятельно vs с приложением</h3><div className="grid sm:grid-cols-2 gap-4 text-sm">{["Искать рецепты по разным сайтам", "Проверять состав каждого продукта", "Вручную считать покупки", "Придумывать семейные варианты", "Разбираться в противоречивых советах"].map((x, i) => <div key={i} className="flex gap-2 text-stone-400"><span>✕</span>{x}</div>)}<div className="sm:col-span-2 border-t border-stone-100 dark:border-white/10 my-1" />{["Готовое меню под ваши условия", "Подходящие рецепты и замены", "Автосписок покупок", "Семейная адаптация и заготовки", "Дневник самочувствия и связь с нутрициологом"].map((x, i) => <div key={i} className="flex gap-2"><span style={{ color: "var(--acc)" }}>✓</span>{x}</div>)}</div></Card>
    {toast && <Toast msg={toast} onClose={() => setToast("")} />}</div>; }

function ProfilePage() { const st = useStore(); const p: any = P(); const [edit, setEdit] = useState(false); const [d, setD] = useState<any>({ ...p });
  const save = () => { if (!d.name.trim()) { alert("Укажите имя"); return; } setSt(s => { Object.assign(s.profile, d); }); setEdit(false); };
  return <div className="p-4 max-w-2xl mx-auto"><h1 className="text-2xl font-bold mb-4">Профиль 👤</h1>
    <Card cls="p-5 mb-4">{edit ? <div><div className="grid grid-cols-2 gap-3"><Field label="Имя"><Input value={d.name} onChange={(e: any) => setD({ ...d, name: e.target.value })} /></Field><Field label="Возраст"><Input type="number" value={d.age} onChange={(e: any) => setD({ ...d, age: e.target.value })} /></Field><Field label="Рост"><Input value={d.height} onChange={(e: any) => setD({ ...d, height: e.target.value })} /></Field><Field label="Вес"><Input value={d.weight} onChange={(e: any) => setD({ ...d, weight: e.target.value })} /></Field></div><Field label="Цель"><Input value={d.goal || ""} onChange={(e: any) => setD({ ...d, goal: e.target.value })} /></Field><Field label="Приёмы пищи"><Seg opts={[{ v: 2, l: "2" }, { v: 3, l: "3" }, { v: 4, l: "4" }]} val={d.meals} set={(v: any) => setD({ ...d, meals: v })} /></Field><div className="grid grid-cols-2 gap-2"><Btn onClick={save}>Сохранить</Btn><Btn variant="soft" onClick={() => { setD({ ...P() }); setEdit(false); }}>Отмена</Btn></div></div> : <div><div className="flex items-center gap-4 mb-4"><div className="w-16 h-16 rounded-2xl flex items-center justify-center text-3xl" style={{ background: "var(--accbg)" }}>{MODE_INFO[MODE()].emoji}</div><div><div className="font-bold text-lg">{p.name || "Гость"}</div><div className="text-xs text-stone-400">{p.age ? p.age + " лет · " : ""}{MODE_INFO[MODE()].title}</div>{st.premium && <span className="text-[10px] px-2 py-0.5 rounded-full text-white font-bold" style={{ background: "var(--acc)" }}>Premium</span>}</div><button className="ml-auto text-xs underline" style={{ color: "var(--acc)" }} onClick={() => setEdit(true)}>Изменить</button></div><div className="text-sm space-y-1.5 text-stone-600 dark:text-stone-300">{p.goal && <div>🎯 Цель: {p.goal}</div>}{p.budget && <div>💰 Бюджет: {p.budget}</div>}{p.cookTime > 0 && <div>⏱ Готовка: до {p.cookTime} мин</div>}{p.disliked.length > 0 && <div>🚫 Не люблю: {p.disliked.join(", ")}</div>}{p.allergies.length > 0 && <div>⚠️ Аллергии: {p.allergies.join(", ")}</div>}{(p.meds || p.diseases) && <div className="text-amber-600">🩺 Есть заболевания/лекарства — согласуйте рацион с врачом</div>}</div></div>}</Card>
    <Card cls="p-4 mb-4"><h3 className="font-bold text-sm mb-3">Достижения 🏅</h3><div className="grid grid-cols-2 gap-2">{ACH.map(a => <div key={a.id} className={`rounded-xl p-3 border ${st.ach[a.id] ? "border-transparent" : "opacity-40"}`} style={st.ach[a.id] ? { background: "var(--accbg)" } : { borderColor: "rgba(120,113,108,.15)" }}><div className="text-xl">{a.e}</div><div className="text-xs font-bold mt-1">{a.t}</div><div className="text-[10px] text-stone-500">{a.d}</div></div>)}</div></Card>
    <div className="grid grid-cols-2 gap-2"><Btn variant="soft" onClick={() => go("#/settings")}>⚙️ Настройки</Btn><Btn variant="soft" onClick={() => { if (confirm("Выйти? Данные сохраняются на устройстве.")) { store.onboarded = false; emit(); location.reload(); } }}>Выйти</Btn></div></div>; }

function SettingsPage() { const st = useStore();
  return <div className="p-4 max-w-2xl mx-auto"><h1 className="text-2xl font-bold mb-4">Настройки ⚙️</h1>
    <Card cls="p-4 mb-4"><h3 className="font-bold text-sm mb-2">Режим питания</h3><Seg opts={[{ v: "keto", l: "🥑 Кето" }, { v: "carnivore", l: "🥩 Карнивор" }, { v: "explore", l: "🔍 Изучаю" }]} val={MODE()} set={(v: any) => setSt(s => { s.profile.mode = v; })} /><div className="text-[11px] text-stone-400 mt-2">Смена режима не удаляет данные — меню можно пересобрать.</div></Card>
    <Card cls="p-4 mb-4"><h3 className="font-bold text-sm mb-3">Оформление</h3><Field label="Тема"><Seg opts={[{ v: "light", l: "☀️ Светлая" }, { v: "dark", l: "🌙 Тёмная" }]} val={st.theme} set={(v: any) => setSt(s => { s.theme = v; })} /></Field>
      <Field label="Акцентный цвет"><div>{Object.entries(ACCENTS).map(([k, v]) => <button key={k} onClick={() => setSt(s => { s.accent = k; })} className="inline-block mr-2"><span className="inline-block w-8 h-8 rounded-full border-2" style={{ background: v.a, borderColor: st.accent === k ? "#fff" : "transparent", boxShadow: st.accent === k ? "0 0 0 2px " + v.a : "none" }} /></button>)}</div><div className="text-xs text-stone-400">{ACCENTS[st.accent].name}</div></Field></Card>
    <Card cls="p-4 mb-4"><h3 className="font-bold text-sm mb-2">Напоминания</h3><Btn variant="soft" onClick={() => go("#/reminders")}>Настроить →</Btn></Card>
    <Card cls="p-4 mb-4"><h3 className="font-bold text-sm mb-3">Информация</h3>{[["Медицинское предупреждение", "#/medical"], ["Политика конфиденциальности", "#/privacy"], ["Пользовательское соглашение", "#/terms"], ["Тарифы", "#/premium"], ["Админ-панель", "#/admin"]].map(([t, l]) => <button key={l} onClick={() => go(l)} className="block w-full text-left py-2 text-sm border-b border-stone-100 dark:border-white/5 last:border-0">{t} →</button>)}</Card>
    <div className="text-center text-[11px] text-stone-400">Кето Баланс v0.9 MVP · данные хранятся локально</div></div>; }

function AdminPage() { const st = useStore(); const [tab, setTab] = useState("recipes"); const [toast, setToast] = useState(""); const [rf, setRf] = useState({ title: "", emoji: "🍽️", mode: "keto", cat: "dinner" });
  const tabs = [["recipes", "Рецепты"], ["programs", "Программы"], ["notifs", "Уведомления"], ["reports", "Отчёты"], ["texts", "Тексты"], ["promo", "Промокоды"], ["stats", "Статистика"]];
  return <div className="p-4 max-w-3xl mx-auto"><h1 className="text-2xl font-bold mb-1">Админ-панель 🛠️</h1><p className="text-xs text-stone-400 mb-4">Демо. В проде: роли, авторизация, защита персональных и медицинских данных.</p>
    <div className="flex gap-2 overflow-x-auto mb-4">{tabs.map(([v, l]) => <Chip key={v} on={tab === v} onClick={() => setTab(v)}>{l}</Chip>)}</div>
    {tab === "recipes" && <Card cls="p-4"><h3 className="font-bold text-sm mb-3">Добавить рецепт</h3><div className="grid grid-cols-2 gap-3"><Field label="Название"><Input value={rf.title} onChange={(e: any) => setRf({ ...rf, title: e.target.value })} /></Field><Field label="Эмодзи"><Input value={rf.emoji} onChange={(e: any) => setRf({ ...rf, emoji: e.target.value })} /></Field><Field label="Режим"><Seg opts={[{ v: "keto", l: "Кето" }, { v: "carnivore", l: "Карнивор" }]} val={rf.mode} set={(v: any) => setRf({ ...rf, mode: v })} /></Field><Field label="Категория"><Seg opts={[{ v: "breakfast", l: "Завтр." }, { v: "lunch", l: "Обед" }, { v: "dinner", l: "Ужин" }]} val={rf.cat} set={(v: any) => setRf({ ...rf, cat: v })} /></Field></div><Btn onClick={() => { if (!rf.title.trim()) { alert("Введите название"); return; } setSt(s => { s.admin = { added: [...(s.admin?.added || []), { ...rf }] }; }); setToast("Рецепт сохранён (демо). Загрузка фото — через CDN."); setRf({ ...rf, title: "" }); }}>Опубликовать</Btn>{st.admin?.added?.map((r: any, i: number) => <div key={i} className="text-xs py-1">✅ {r.emoji} {r.title}</div>)}</Card>}
    {tab === "programs" && <Card cls="p-4"><h3 className="font-bold text-sm mb-2">Опубликованные программы</h3>{PROGRAMS.map(p => <div key={p.id} className="flex justify-between py-1.5 text-sm border-b border-stone-100 dark:border-white/5"><span>{p.emoji} {p.title}</span><span className="text-xs text-emerald-600">активна</span></div>)}</Card>}
    {tab === "notifs" && <Card cls="p-4"><h3 className="font-bold text-sm mb-2">Массовое уведомление</h3><textarea rows={3} className="w-full px-3.5 py-2.5 rounded-xl border border-stone-200 dark:border-white/15 bg-white dark:bg-white/5 text-sm outline-none mb-3" placeholder="Например: новые рецепты уже в приложении 🍳" /><Btn onClick={() => setToast("Отправка push подключается отдельно")}>Отправить всем</Btn></Card>}
    {tab === "reports" && <Card cls="p-4"><h3 className="font-bold text-sm mb-2">Отчёты пользователей</h3><p className="text-xs text-stone-500 mb-3">Доступны только при согласии пользователя. Данные защищены.</p>{st.msgs.length > 0 ? <div>{st.msgs.slice(-3).map((m0: any) => <div key={m0.id} className="py-1 text-xs bg-stone-50 dark:bg-white/5 rounded-lg px-2 mb-1">{m0.text}</div>)}</div> : <div className="text-xs text-stone-400">Пока нет отчётов.</div>}</Card>}
    {tab === "texts" && <Card cls="p-4"><h3 className="font-bold text-sm mb-2">Текст на главной</h3><Field label="Подзаголовок"><Input value={st.homeTxt.sub} onChange={(e: any) => setSt(s => { s.homeTxt.sub = e.target.value; })} /></Field><Btn onClick={() => setToast("Сохранено ✅")}>Сохранить</Btn></Card>}
    {tab === "promo" && <Card cls="p-4"><h3 className="font-bold text-sm mb-2">Промокоды</h3><div className="flex gap-2 mb-3"><Input placeholder="KETO20" /><Btn onClick={() => setToast("Промокод создан (демо). Активация через биллинг.")}>Создать</Btn></div><div className="text-xs text-stone-500">WELCOME10 — скидка 10% (демо)</div></Card>}
    {tab === "stats" && <Card cls="p-4"><h3 className="font-bold text-sm mb-3">Обезличенная статистика</h3><div className="grid grid-cols-3 gap-3 text-center">{[["37", "рецептов"], ["15", "уроков"], ["9", "программ"]].map(([v, l]) => <div key={l}><div className="text-2xl font-bold" style={{ color: "var(--acc)" }}>{v}</div><div className="text-[11px] text-stone-400">{l}</div></div>)}</div><div className="text-xs text-stone-400 mt-3">Реальная аналитика подключается к бэкенду.</div></Card>}
    {toast && <Toast msg={toast} onClose={() => setToast("")} />}</div>; }

function ChatWidget() { const st = useStore(); const [open, setOpen] = useState(false); const [msg, setMsg] = useState(""); const [typing, setTyping] = useState(false); const ref = useRef<any>(null);
  useEffect(() => { if (ref.current) ref.current.scrollTop = ref.current.scrollHeight; }, [open, store.chat.length, typing]);
  const send = () => { if (!msg.trim()) return; const t = msg; setSt(s => { s.chat.push({ from: "me", text: t }); }); setMsg(""); setTyping(true); setTimeout(() => { setSt(s => { s.chat.push({ from: "bot", text: botReply(t) }); }); setTyping(false); }, 700); };
  return <div><button onClick={() => setOpen(!open)} className="fixed bottom-20 right-4 z-40 w-12 h-12 rounded-full shadow-lg text-white text-xl" style={{ background: "var(--acc)" }}>💬</button>{open && <div className="fixed bottom-20 right-4 z-50 w-[calc(100%-2rem)] sm:w-80"><Card cls="overflow-hidden shadow-2xl"><div className="p-3 text-white flex justify-between items-center" style={{ background: "var(--acc)" }}><div className="text-sm font-bold">🤖 Кето-помощник</div><button onClick={() => setOpen(false)}>✕</button></div><div ref={ref} className="h-64 overflow-y-auto p-3 space-y-2">{store.chat.length === 0 && <div className="text-xs text-stone-400 text-center pt-8">Спросите про кето, карнивор, меню или самочувствие.</div>}{store.chat.map((m0: any, i: number) => <div key={i} className={`max-w-[85%] rounded-2xl px-3 py-2 text-sm ${m0.from === "me" ? "ml-auto text-white" : "bg-stone-100 dark:bg-white/10"}`} style={m0.from === "me" ? { background: "var(--acc)" } : {}}>{m0.text}</div>)}{typing && <div className="text-xs text-stone-400">печатает…</div>}</div><div className="p-2 flex gap-2 border-t border-stone-100 dark:border-white/10"><input value={msg} onChange={(e: any) => setMsg(e.target.value)} onKeyDown={(e: any) => e.key === "Enter" && send()} placeholder="Сообщение…" className="flex-1 px-3 py-2 rounded-xl border border-stone-200 dark:border-white/15 bg-white dark:bg-white/5 text-sm outline-none" /><button onClick={send} className="px-3 rounded-xl text-white" style={{ background: "var(--acc)" }}>→</button></div></Card></div>}</div>; }

function LegalPage({ k }: any) { const l = Legal[k]; return <div className="p-4 max-w-2xl mx-auto"><button onClick={() => go("#/settings")} className="text-sm text-stone-500 mb-3">← Назад</button><h1 className="text-2xl font-bold mb-4">{l.t}</h1>{l.b.map((p, i) => <p key={i} className="text-sm mb-3 text-stone-600 dark:text-stone-300">{p}</p>)}{k === "medical" && <div className="rounded-2xl bg-red-50 dark:bg-red-950/40 border border-red-300 p-4 text-sm font-semibold text-red-700 dark:text-red-300 mt-4">Экстренная помощь: 103 или 112</div>}</div>; }

/* ================= 7. КАРКАС И РОУТЕР ================= */
const NAV: [string, string, string][] = [["home", "Главная", "🏠"], ["recipes", "Рецепты", "🍳"], ["menu", "Меню", "📅"], ["diary", "Дневник", "📔"], ["more", "Ещё", "☰"]];
const MORE: [string, string, string][] = [["choose", "Какой формат подойдёт", "🧭"], ["quiz", "Тест подбора плана", "📝"], ["programs", "Программы", "🎯"], ["budget", "Без лишних расходов", "💰"], ["builder", "Собрать блюдо", "🧩"], ["shopping", "Список покупок", "🛒"], ["fridge", "Мой холодильник", "🧊"], ["prep", "Заготовки", "📦"], ["stats", "Динамика", "📈"], ["report", "Недельный отчёт", "📊"], ["learn", "Начало пути", "🎓"], ["cafe", "Что выбрать в кафе", "🍽️"], ["navigator", "Навигатор в магазине", "🛍️"], ["antisryv", "Антисрыв", "🍬"], ["reminders", "Напоминания", "⏰"], ["nutritionist", "Мой нутрициолог", "💬"], ["premium", "Тарифы", "✨"], ["profile", "Профиль", "👤"], ["settings", "Настройки", "⚙️"]];
function Shell({ children, path }: any) { const st = useStore(); const [more, setMore] = useState(false); const cur = path.split("/")[0];
  return <div className="min-h-screen pb-24 lg:pb-8 lg:pl-60" style={{ background: "var(--bg)" }}>
    <aside className="hidden lg:flex flex-col fixed left-0 top-0 bottom-0 w-60 border-r border-stone-200/70 dark:border-white/10 p-4" style={{ background: "var(--card)" }}>
      <div className="flex items-center gap-2 mb-6 cursor-pointer" onClick={() => go("#/home")}><span className="text-2xl">🥑</span><b className="text-lg">Кето Баланс</b></div>
      <div className="flex-1 overflow-y-auto space-y-0.5">{[["home", "Главная", "🏠"], ["recipes", "Рецепты", "🍳"], ["menu", "Меню", "📅"], ["shopping", "Покупки", "🛒"], ["diary", "Дневник", "📔"], ["stats", "Динамика", "📈"], ["learn", "Обучение", "🎓"], ["programs", "Программы", "🎯"], ["choose", "Какой формат", "🧭"], ["cafe", "В кафе", "🍽️"], ["navigator", "Навигатор", "🛍️"], ["nutritionist", "Нутрициолог", "💬"], ["premium", "Premium", "✨"], ["profile", "Профиль", "👤"], ["settings", "Настройки", "⚙️"], ["admin", "Админ", "🛠️"]].map(([id, l, e]) => <button key={id} onClick={() => go("#/" + id)} className={`w-full flex items-center gap-3 px-3 py-2.5 rounded-xl text-sm font-medium text-left ${cur === id ? "text-white" : ""}`} style={cur === id ? { background: "var(--acc)" } : {}}>{e} {l}</button>)}</div>
      {!st.premium && <button onClick={() => go("#/premium")} className="mt-3 rounded-xl p-3 text-left text-white text-xs" style={{ background: "linear-gradient(135deg,var(--acc),var(--acc2))" }}><b>✨ Premium</b><div className="opacity-80 mt-0.5">Все рецепты, меню и аналитика</div></button>}
    </aside>
    <header className="lg:hidden sticky top-0 z-30 flex items-center justify-between px-4 py-3 border-b border-stone-200/60 dark:border-white/10" style={{ background: "var(--bg)" }}>
      <div className="flex items-center gap-2 cursor-pointer" onClick={() => go("#/home")}><span className="text-xl">🥑</span><b>Кето Баланс</b></div>
      <div className="flex items-center gap-2">{st.premium && <span className="text-[10px] px-2 py-1 rounded-full text-white font-bold" style={{ background: "var(--acc)" }}>PRO</span>}<button onClick={() => setSt(s => { s.theme = s.theme === "light" ? "dark" : "light"; })} className="w-9 h-9 rounded-full bg-black/5 dark:bg-white/10">{st.theme === "light" ? "🌙" : "☀️"}</button></div>
    </header>
    <main>{children}</main>
    <nav className="lg:hidden fixed bottom-0 left-0 right-0 z-40 border-t border-stone-200/70 dark:border-white/10 flex" style={{ background: "var(--card)" }}>
      {NAV.map(([id, l, e]) => <button key={id} onClick={() => { id === "more" ? setMore(true) : go("#/" + id); }} className="flex-1 py-2.5 flex flex-col items-center gap-0.5"><span className={`text-xl ${cur === id ? "" : "grayscale opacity-60"}`}>{e}</span><span className="text-[10px] font-semibold" style={cur === id ? { color: "var(--acc)" } : {}}>{l}</span></button>)}
    </nav>
    {more && <div className="fixed inset-0 z-50 bg-black/40 flex items-end" onClick={() => setMore(false)}><div className="w-full bg-[#FDFBF6] dark:bg-[#26221C] rounded-t-3xl p-5 max-h-[80vh] overflow-y-auto" onClick={(e: any) => e.stopPropagation()}><div className="flex justify-between items-center mb-4"><b className="text-lg">Разделы</b><button onClick={() => setMore(false)}>✕</button></div><div className="grid grid-cols-2 gap-2">{MORE.map(([id, l, e]) => <button key={id} onClick={() => { setMore(false); go("#/" + id); }} className="flex items-center gap-2 px-3 py-3 rounded-xl bg-black/5 dark:bg-white/5 text-sm font-medium">{e} {l}</button>)}</div><button onClick={() => { setMore(false); go("#/admin"); }} className="mt-3 text-xs text-stone-400 underline">Админ-панель</button></div></div>}
  </div>; }

function Router() { const r = useRoute(); const st = useStore();
  if (!st.onboarded || !st.profile.name) return <Onboarding />;
  const map: any = { "/home": <HomePage />, "/recipes": <RecipesPage />, "/recipe": <RecipePage id={r.parts[1]} />, "/builder": <BuilderPage />, "/menu": <MenuPage />, "/shopping": <ShoppingPage />, "/fridge": <FridgePage />, "/diary": <DiaryPage />, "/stats": <StatsPage />, "/report": <ReportPage />, "/keto": <ModePage mode="keto" />, "/carnivore": <ModePage mode="carnivore" />, "/choose": <ChoosePage />, "/quiz": <QuizPage />, "/programs": <ProgramsPage />, "/budget": <BudgetPage />, "/learn": <LearnPage />, "/cafe": <CafePage />, "/navigator": <NavigatorPage />, "/prep": <PrepPage />, "/antisryv": <AntisryvPage />, "/reminders": <RemindersPage />, "/nutritionist": <NutritionistPage />, "/premium": <PremiumPage />, "/profile": <ProfilePage />, "/settings": <SettingsPage />, "/admin": <AdminPage />, "/privacy": <LegalPage k="privacy" />, "/terms": <LegalPage k="terms" />, "/medical": <LegalPage k="medical" /> };
  return <Shell path={r.path}>{map[r.path] || <Empty e="🧭" t="Страница не найдена" btn="На главную" onClick={() => go("#/home")} />}<ChatWidget /></Shell>; }

export default function App() { const st = useStore(); const a = ACCENTS[st.accent] || ACCENTS.sage;
  const vars: any = { "--acc": a.a, "--acc2": a.a2, "--accbg": st.theme === "dark" ? a.a + "2e" : a.bg, "--bg": st.theme === "dark" ? a.dk : "#F7F2E9", "--card": st.theme === "dark" ? "#26221C" : "#FFFFFF", "--ink": st.theme === "dark" ? "#F1EDE4" : "#2B2620" };
  return <div className={st.theme === "dark" ? "dark" : ""} style={{ ...vars, background: "var(--bg)", color: "var(--ink)", minHeight: "100vh", fontFamily: "'Manrope',system-ui,sans-serif" }}><Router /></div>; }
